/* q = words people use (English and Spanish, no accents needed). */
const KB = [
  /* ---------- medical ---------- */
  { id: 'MED-01', cat: 'medical', title: 'Headache', q: 'headache head hurts head pain dolor de cabeza cefalea me duele la cabeza',
    a: 'In space, headaches are most often caused by high cabin CO₂, the fluid shift toward the head, short sleep or dehydration.',
    steps: ['Check cabin CO₂ on the display and move to a well-ventilated module.', 'Drink 250–500 mL of water.', 'Rest with the lights low for 20 minutes.', 'Log your blood pressure and sleep.'],
    esc: 'Sudden or worst-ever headache, or headache with vision change, confusion, weakness or vomiting: tell the Crew Medical Officer now.', src: ['sans', 'std2'] },
  { id: 'MED-02', cat: 'medical', title: 'Space motion sickness, nausea and vomiting', q: 'nausea vomit sick motion sickness space adaptation queasy nauseas vomito mareo malestar estomago',
    a: 'Common in the first 2–3 days of weightlessness or after returning to gravity. The inner ear and eyes disagree about which way is down.',
    steps: ['Keep your head still and look at a fixed visual "floor".', 'Sip fluids; eat small, bland portions.', 'Keep an emesis bag within reach — vomit floats.', 'Anti-nausea medicine only through the medication check (it applies your allergies and other medicines).'],
    esc: 'Vomiting for more than 24 h, blood, or nausea with chest pain or severe headache: Crew Medical Officer.', src: ['sensori'] },
  { id: 'MED-03', cat: 'medical', title: 'Dizziness or fainting on standing (after landing or in gravity)', q: 'dizzy dizziness faint lightheaded orthostatic standing up mareado desmayo vahido presion baja',
    a: 'Without gravity, plasma volume falls and the heart deconditions, so blood pressure can drop when you stand in gravity again.',
    steps: ['Sit or lie down with legs raised.', 'Drink 500 mL of water or an electrolyte drink.', 'Measure blood pressure lying and then standing.', 'Stand up slowly, in stages.'],
    esc: 'Fainting, chest pain or a fast irregular heartbeat: Crew Medical Officer now.', src: ['cv'] },
  { id: 'MED-04', cat: 'medical', title: 'Back pain', q: 'back pain backache spine lower back dolor de espalda lumbar columna',
    a: 'The spine lengthens 4–6 cm in microgravity and back pain is very common in the first weeks.',
    steps: ['Curl into the fetal position for a few minutes to unload the spine.', 'Gentle stretching and core exercise.', 'Heat or cold packs from the medical kit.', 'Pain relief through the medication check.'],
    esc: 'Back pain with numbness, leg weakness or trouble controlling bladder or bowel: urgent.', src: ['fit'] },
  { id: 'MED-05', cat: 'medical', title: 'Blocked nose and puffy face ("space cold")', q: 'stuffy nose congestion sinus puffy face nariz tapada congestion senos paranasales cara hinchada',
    a: 'Fluid shifts toward the head and causes congestion and a puffy face. It is not an infection.',
    steps: ['Saline nasal rinse or spray.', 'Sleep with the head slightly elevated in gravity.', 'Stay hydrated.'],
    esc: 'Fever, facial pain or thick discharge suggest infection: log temperature and tell the Crew Medical Officer.', src: ['sans'] },
  { id: 'MED-06', cat: 'medical', title: 'Fever or possible infection', q: 'fever chills infection flu cold cough sore throat fiebre escalofrios infeccion gripe tos garganta resfriado',
    a: 'Immune function changes in space and germs spread fast in a closed cabin.',
    steps: ['Log temperature, heart rate and SpO₂.', 'Wear a mask, wash hands often, do not share food or utensils.', 'Rest and drink fluids.', 'Wipe shared surfaces.'],
    esc: 'Temperature 38.5 °C or higher, SpO₂ under 94%, or breathing difficulty: Crew Medical Officer today.', src: ['immune', 'micro'] },
  { id: 'MED-07', cat: 'medical', title: 'Constipation or bloating', q: 'constipation bloating gas stomach ache estrenimiento estrenido gases hinchazon barriga',
    a: 'Low fluid intake, less activity and the space diet slow the gut.',
    steps: ['Drink at least 2 L a day.', 'Choose high-fibre menu items and fruit.', 'Daily exercise.'],
    esc: 'Severe abdominal pain, fever or no bowel movement for 4+ days: Crew Medical Officer.', src: ['food'] },
  { id: 'MED-08', cat: 'medical', title: 'Kidney stone warning signs', q: 'kidney stone flank pain side pain blood in urine renal calculo rinon dolor de costado sangre en orina',
    a: 'Bone loss releases calcium and low fluid intake concentrates urine, raising kidney stone risk.',
    steps: ['Drink enough to pass about 2 L of urine a day.', 'Limit salt.', 'Note pain that comes in waves from the side to the groin.'],
    esc: 'Severe side pain, blood in urine, fever or vomiting: Crew Medical Officer now.', src: ['renal'] },
  { id: 'MED-09', cat: 'medical', title: 'Vision change (SANS)', q: 'vision blurry eyes blur sans near vision eye vista borrosa ojos vision cercana',
    a: 'Fluid shift raises pressure behind the eye. Near vision may blur gradually over months.',
    steps: ['Log vision change in Vitals.', 'Use the adjustable or "space anticipation" glasses if issued.', 'Report at the next medical conference for an eye exam.'],
    esc: 'Sudden loss of vision, flashes, a curtain over the eye or eye pain: urgent.', src: ['sans'] },
  { id: 'MED-10', cat: 'medical', title: 'Something in the eye or eye irritation', q: 'eye irritation particle debris red eye dust ojo irritado particula basura ojo rojo polvo',
    a: 'Particles do not fall in microgravity, so dust and debris often reach the eyes.',
    steps: ['Do not rub.', 'Flush with saline eyewash or clean water for several minutes.', 'Wear eye protection near dusty work.'],
    esc: 'Pain that persists, vision change or a chemical in the eye: flush for 15 minutes and call the Crew Medical Officer.', src: ['dust'] },
  { id: 'MED-11', cat: 'medical', title: 'Skin irritation, rash or slow-healing cuts', q: 'skin rash itch dry skin cut wound healing piel sarpullido picazon piel seca corte herida cicatrizar',
    a: 'Skin gets thinner and drier in space and wounds can heal more slowly.',
    steps: ['Moisturise daily.', 'Clean cuts, cover them and keep them dry.', 'Check the area every day for redness or pus.'],
    esc: 'Spreading redness, pus, fever or hives with swelling of the face: Crew Medical Officer (hives with swelling may be an allergic reaction — emergency).', src: ['immune'] },
  { id: 'MED-12', cat: 'medical', title: 'Toothache or broken tooth', q: 'tooth toothache dental broken filling diente dolor de muela muela rota empaste',
    a: 'Dental problems are among the most common in-flight medical events.',
    steps: ['Rinse with warm water.', 'Use the dental kit temporary filling material if the filling fell out.', 'Pain relief through the medication check.'],
    esc: 'Facial swelling or fever: possible abscess — Crew Medical Officer today.', src: ['med'] },
  { id: 'MED-13', cat: 'medical', title: 'Muscle or bone loss', q: 'muscle loss bone loss weakness atrophy osteoporosis perdida muscular perdida osea debilidad huesos musculos',
    a: 'Unloaded bones lose about 1–1.5% of density per month and muscles weaken within weeks.',
    steps: ['Do the full exercise prescription daily: resistance plus aerobic.', 'Eat enough protein and take vitamin D as prescribed.', 'Log exercise and body mass.'],
    esc: 'Bone pain after minor impact may be a fracture — immobilise and call the Crew Medical Officer.', src: ['bone', 'fit'] },
  { id: 'MED-14', cat: 'medical', title: 'Chest pain or palpitations', q: 'chest pain palpitations heart racing irregular heartbeat dolor de pecho palpitaciones corazon acelerado arritmia',
    a: 'Chest pain is always treated as serious until proven otherwise.',
    steps: ['Stop all activity and rest, restrained.', 'Measure blood pressure, heart rate and SpO₂.', 'Open the emergency protocol "Chest pain".'],
    esc: 'Call the Crew Medical Officer now and open emergency help.', src: ['cv'], emg: 'chest' },
  { id: 'MED-15', cat: 'medical', title: 'Shortness of breath', q: 'short of breath breathless breathing difficult wheezing falta de aire me ahogo respirar cuesta respirar silbido',
    a: 'Check the cabin air first, then the person.',
    steps: ['Check CO₂ and alarms.', 'Measure SpO₂.', 'Give oxygen if SpO₂ is under 94% (emergency protocol).'],
    esc: 'Breathless at rest or SpO₂ under 90%: emergency.', src: ['hypoxia', 'std2'], emg: 'breathing' },
  { id: 'MED-16', cat: 'medical', title: 'Radiation exposure and solar particle events', q: 'radiation dose solar storm particle event spe shelter radiacion dosis tormenta solar refugio',
    a: 'During a solar particle event the dose rate can jump; shielding is the main protection.',
    steps: ['Go to the designated shielded area (storm shelter) as soon as the alert sounds.', 'Wear your personal dosimeter and log the reading.', 'Postpone EVAs until the event ends.'],
    esc: 'Nausea, vomiting or skin redness after a large event: Crew Medical Officer and ground.', src: ['rad', 'std1'] },
  { id: 'MED-17', cat: 'medical', title: 'Decompression sickness after EVA', q: 'decompression sickness bends joint pain after eva spacewalk enfermedad descompresion dolor articulaciones caminata espacial',
    a: 'Nitrogen bubbles can form if pressure drops too fast — joint pain, tingling or confusion after an EVA.',
    steps: ['Report any joint pain, skin itching or tingling after EVA immediately.', 'Breathe 100% oxygen.', 'The suit or airlock can be repressurised as a treatment per the EVA checklist.'],
    esc: 'Any neurological symptom (numbness, weakness, confusion) after EVA: emergency.', src: ['dcs'] },
  { id: 'MED-18', cat: 'medical', title: 'Medicines in space', q: 'medicine expired potency medication works pills shelf life medicamento caducado vencido funciona pastillas',
    a: 'Some medicines lose potency faster in space (radiation, temperature). The rules engine checks allergies, interactions and dose; stock comes from the ship inventory.',
    steps: ['Use the Questions medication check before any medicine ("Can I take …?").', 'Check the expiry date on the label.', 'Log what you took in the ship inventory (Use one).'],
    esc: 'Unsure about a dose or the medicine had no effect: ask the Crew Medical Officer.', src: ['pharm'] },
  { id: 'MED-19', cat: 'medical', title: 'Cuts and minor bleeding', q: 'cut bleeding minor wound scrape corte sangrado herida rasguno raspon',
    a: 'Most small cuts stop with pressure. In microgravity, blood forms floating droplets.',
    steps: ['Gloves on; press with a dressing for 10 minutes.', 'Clean with saline, close with strips, cover.', 'Check daily for infection.'],
    esc: 'Bleeding that will not stop with pressure: emergency protocol "Severe bleeding".', src: ['med'], emg: 'bleeding' },
  { id: 'MED-20', cat: 'medical', title: 'Burns', q: 'burn scald hot surface quemadura quemado superficie caliente',
    a: 'Cool first, cover second.',
    steps: ['Cool with water or cold packs for 20 minutes.', 'Remove rings or tight items.', 'Cover loosely with a burn dressing or cling film.'],
    esc: 'Burns to face, hands or airway, or larger than the palm: emergency protocol "Burn".', src: ['med'], emg: 'burn' },

  { id: 'MED-21', cat: 'medical', title: 'Joint, muscle or limb pain', q: 'knee shoulder ankle wrist elbow hip joint muscle sore strain sprain arm leg hurts rodilla hombro tobillo muneca codo cadera articulacion musculo dolor brazo pierna duele esguince',
    a: 'Joint and muscle pain is common with exercise devices and moving through tight modules; in microgravity it is easy to strain a muscle when stopping a movement.',
    steps: ['Rest the area and avoid loading it for 24 h.', 'Cold pack (wrapped) for 20 minutes, a few times a day.', 'Gentle movement once the pain allows.', 'Pain relief through the medication check.'],
    esc: 'Deformity, a crack sound, inability to move it, or swelling that grows: possible fracture — emergency protocol "Possible fracture".', src: ['fit', 'bone'], emg: 'fracture' },

  /* ---------- emotional wellbeing ---------- */
  { id: 'WB-01', cat: 'wellbeing', title: 'Feeling sad, down or low', q: 'sad down low depressed depression unhappy crying hopeless worthless empty triste tristeza deprimido depresion bajo de animo llorar lloro desanimado vacio sin esperanza inutil',
    a: 'Low mood is common on long missions — isolation, distance from home and workload add up. It is treatable and it is not a personal failing.',
    steps: ['Tell someone you trust on the crew how you feel.', 'Request a private psychological conference — it is confidential.', 'Keep sleep, meals and exercise regular this week.', 'Plan something to look forward to (a call home, a film night).'],
    esc: 'Thoughts of harming yourself, or several days unable to work: tell the Crew Medical Officer today and request an urgent conference.', src: ['bmed'] },
  { id: 'WB-02', cat: 'wellbeing', title: 'Anxiety or panic', q: 'anxiety anxious panic attack nervous worried fear ansiedad ansioso ataque de panico nervioso preocupado miedo',
    a: 'Anxiety is a normal response to a high-stakes environment. The body\'s alarm can be calmed.',
    steps: ['Breathe in for 4 seconds, hold 2, out for 6 — for 3 minutes.', 'Name 5 things you see, 4 you hear, 3 you can touch.', 'Move to a quiet module and anchor yourself to a handhold.', 'Tell a crewmate what is happening.'],
    esc: 'Panic that does not settle in 20 minutes, or chest pain: check vitals and call the Crew Medical Officer.', src: ['bmed'] },
  { id: 'WB-03', cat: 'wellbeing', title: 'Stress and overload', q: 'stress stressed overwhelmed too much work overload burnout estres estresado agobiado mucho trabajo sobrecarga',
    a: 'Workload, time pressure and little control are the main stressors on long missions.',
    steps: ['Write the 3 tasks that matter most today; tell ground what to move.', 'Take a 10-minute break every 2 hours.', 'Exercise — it is one of the best stress relievers.', 'Protect your sleep window.'],
    esc: 'Stress affecting safety-critical work: tell the commander so tasks can be re-planned.', src: ['bmed', 'sleep'] },
  { id: 'WB-04', cat: 'wellbeing', title: 'Insomnia and poor sleep', q: 'cant sleep insomnia sleep badly awake at night tired no puedo dormir insomnio duermo mal desvelado cansado',
    a: 'Light, noise, CO₂, workload and a 90-minute day–night cycle disturb sleep in space.',
    steps: ['Dim lights and avoid screens 1 hour before sleep.', 'Use earplugs and an eye mask; check sleep-station airflow and CO₂.', 'Keep the same sleep window every day.', 'Avoid caffeine after midday.'],
    esc: 'Fewer than 6 hours for 3+ nights: ask ground to protect a full sleep window; sleep medicine only through the Crew Medical Officer.', src: ['sleep'] },
  { id: 'WB-05', cat: 'wellbeing', title: 'Homesickness and missing family', q: 'homesick miss family miss home lonely nostalgia extrano a mi familia extrano casa solo soledad',
    a: 'Missing home is one of the most frequent feelings on long missions.',
    steps: ['Schedule a family call or record a message.', 'Keep photos or a small object from home at your station.', 'Share it with the crew — others feel it too.'],
    esc: 'If it stops you sleeping or working: request a psychological conference.', src: ['bmed'] },
  { id: 'WB-06', cat: 'wellbeing', title: 'Conflict with a crewmate', q: 'conflict argument fight crewmate angry tension discusion pelea companero enojado tension',
    a: 'Small frictions grow in confinement. Early, calm talk prevents them.',
    steps: ['Wait until you are both calm; talk in private.', 'Describe the situation and how it affects you — not the person.', 'Agree on one concrete change.', 'Use the commander or a ground mediator if it does not settle.'],
    esc: 'Conflict affecting safety or teamwork: tell the commander.', src: ['team'] },
  { id: 'WB-07', cat: 'wellbeing', title: 'Bad news from home or grief', q: 'bad news grief death loss family emergency mala noticia duelo muerte perdida emergencia familiar',
    a: 'Receiving hard news far from home is one of the toughest parts of a mission.',
    steps: ['You can pause non-critical work — tell the commander.', 'Request a private call with family and with the psychological support team.', 'Let the crew support you; you do not have to be alone.'],
    esc: 'If you cannot sleep or function: Crew Medical Officer and an urgent psychological conference.', src: ['bmed'] },
  { id: 'WB-08', cat: 'wellbeing', title: 'Boredom and monotony', q: 'bored boredom monotony same routine aburrido aburrimiento monotonia rutina',
    a: 'Monotony lowers motivation and alertness over long missions.',
    steps: ['Vary your routine where you can (new music, a project, a hobby).', 'Plan crew activities: shared meals, films, games.', 'Set personal goals (learn something, photograph Earth).'],
    esc: 'Persistent loss of interest in everything may be low mood: see "Feeling sad".', src: ['bmed'] },
  { id: 'WB-09', cat: 'wellbeing', title: 'Fatigue and low energy', q: 'fatigue tired no energy exhausted cansancio fatiga sin energia agotado',
    a: 'Fatigue usually follows short sleep, stress or overwork — and it is easy not to notice.',
    steps: ['Check your sleep log for the last 5 nights.', 'Pair up on safety-critical tasks.', 'Short breaks, hydration and a balanced meal.'],
    esc: 'Fatigue with fever, shortness of breath or chest pain: Crew Medical Officer.', src: ['sleep'] },
  { id: 'WB-10', cat: 'wellbeing', title: 'Fear before an EVA or a critical task', q: 'scared eva spacewalk nervous critical task fear miedo caminata espacial nervioso tarea critica',
    a: 'Being nervous before high-risk work is normal and can sharpen focus.',
    steps: ['Rehearse the procedure with your partner.', 'Use slow breathing before starting.', 'Agree on clear stop words and check-ins.'],
    esc: 'If fear stops you from performing safely, tell the commander — postponing is an option.', src: ['bmed'] },

  /* ---------- more medical ---------- */
  { id: 'MED-22', cat: 'medical', title: 'Sore throat, cough and congestion', q: 'sore throat cough cold congestion runny nose dolor de garganta tos resfriado gripe mocos congestion catarro',
    a: 'Most are viral and settle in a week. In the cabin they spread easily, and a weaker immune system in flight can make them last longer.',
    steps: ['Log your temperature and SpO₂ today.', 'Drink warm fluids and rest your voice.', 'Wash hands often, use your own cup and cover coughs.', 'Medicine only through the medication check (it applies your allergies).'],
    esc: 'Fever over 38 °C, breathlessness, SpO₂ under 94%, or no improvement after 5 days: tell the Crew Medical Officer.', src: ['immune', 'micro'] },
  { id: 'MED-23', cat: 'medical', title: 'Diarrhoea or stomach pain', q: 'diarrhea diarrhoea stomach ache belly pain cramps loose stool diarrea dolor de estomago panza barriga colicos abdominal',
    a: 'Usually from food, stress or a mild infection. In space the main danger is losing fluids, because thirst is weaker.',
    steps: ['Drink small sips often; add an electrolyte packet to each pouch.', 'Eat small, bland portions.', 'Log hydration and temperature.', 'Use your own hygiene wipes and clean the toilet area after use.'],
    esc: 'Blood in the stool, fever, severe or constant pain, pain in the lower right belly, or more than 6 episodes a day: tell the Crew Medical Officer now.', src: ['food', 'micro'] },
  { id: 'MED-24', cat: 'medical', title: 'Heartburn or indigestion', q: 'heartburn reflux indigestion acid burning chest after eating acidez agruras reflujo indigestion ardor estomago',
    a: 'Without gravity, stomach acid moves up more easily, especially after large meals.',
    steps: ['Eat smaller meals and avoid eating in the 2 hours before sleep.', 'Cut down on coffee and spicy food for a few days.', 'Antacid only through the medication check.'],
    esc: 'Chest pain that spreads to the arm, jaw or back, or comes with breathlessness or sweating, is not heartburn until proven otherwise: press Help.', src: ['food', 'cv'] },
  { id: 'MED-25', cat: 'medical', title: 'Burning when urinating or urinary infection', q: 'burning urination pee pain urinary infection uti bladder ardor al orinar orinar duele infeccion urinaria vejiga orina',
    a: 'Low fluid intake and changes in the urine in flight make urinary infections and kidney stones more likely.',
    steps: ['Drink at least 2.5 L today.', 'Do a urine dipstick test and log it (Vitals → Urine test).', 'Log your temperature.'],
    esc: 'Fever, pain in the side or back, or blood in the urine: tell the Crew Medical Officer today — it may need antibiotics.', src: ['renal', 'micro'] },
  { id: 'MED-26', cat: 'medical', title: 'Nosebleed', q: 'nosebleed nose bleeding bloody nose epistaxis sangra la nariz sangrado nasal sangre de la nariz',
    a: 'Common in flight: the cabin air is dry and the fluid shift fills the vessels in the head. Blood does not drip in microgravity — it collects.',
    steps: ['Sit, lean slightly forward and pinch the soft part of the nose for 10 minutes without letting go.', 'Catch the blood with gauze so droplets do not float.', 'Breathe through the mouth; do not lie back.', 'Afterwards, avoid blowing your nose for a day.'],
    esc: 'Bleeding that does not stop after 20 minutes of pressure, or if you take a blood thinner: tell the Crew Medical Officer now.', src: ['med'] },
  { id: 'MED-27', cat: 'medical', title: 'Ear pain or ear pressure', q: 'ear pain earache ear pressure blocked ears ringing dolor de oido oreja oidos tapados presion en los oidos zumbido',
    a: 'Usually from pressure changes, congestion or noise. Ringing after loud noise is a warning to protect your hearing.',
    steps: ['Swallow or yawn to equalise; do not force air through a blocked nose.', 'Use earplugs in loud modules and during sleep.', 'Log any ringing or hearing change.'],
    esc: 'Sudden hearing loss, discharge from the ear, severe pain or dizziness: tell the Crew Medical Officer today.', src: ['std2', 'med'] },
  { id: 'MED-28', cat: 'medical', title: 'Muscle cramps', q: 'cramp cramps muscle spasm charley horse calambre calambres espasmo muscular tiron',
    a: 'Often from fluid and salt loss, hard exercise or long periods without moving.',
    steps: ['Stretch the muscle gently and hold for 30 seconds.', 'Drink a pouch with an electrolyte packet.', 'Warm up before resistance exercise.'],
    esc: 'Cramps with weakness, dark urine or a swollen, painful calf: tell the Crew Medical Officer — rule out a clot or muscle damage.', src: ['fit'] },
  { id: 'MED-29', cat: 'medical', title: 'Numbness or tingling', q: 'numbness tingling pins and needles hands feet hormigueo entumecido adormecido manos pies cosquilleo',
    a: 'Brief tingling from pressure on a nerve (a tight restraint, sleeping on an arm) is common and goes away when you move.',
    steps: ['Change position and loosen straps or gloves.', 'Note where it is and how long it lasts.'],
    esc: 'Sudden numbness or weakness of the face, arm or leg on one side, trouble speaking or seeing, or tingling after an EVA: emergency — press Help (stroke or decompression sickness).', src: ['dcs', 'med'] },
  { id: 'MED-30', cat: 'medical', title: 'High blood pressure reading', q: 'high blood pressure hypertension bp high reading presion alta hipertension tension alta presion arterial alta',
    a: 'A single high reading is often caused by stress, caffeine, a full bladder or the cuff. What matters is whether it stays high.',
    steps: ['Sit still for 5 minutes, arm at heart level, and measure again.', 'Go easy on salt and caffeine today.', 'Measure at the same time tomorrow.'],
    esc: 'Systolic 180 or more, or high pressure with headache, chest pain, vision change or confusion: tell the Crew Medical Officer now.', src: ['cv', 'std1'] },
  { id: 'MED-31', cat: 'medical', title: 'Low blood sugar (shaky, sweaty, hungry)', q: 'low blood sugar hypoglycemia shaky sweaty hungry weak azucar baja glucosa baja hipoglucemia tembloroso sudoroso',
    a: 'Skipping meals during long tasks can drop blood sugar: shakiness, sweating, hunger, poor concentration.',
    steps: ['Take 15–20 g of fast sugar now (glucose gel or a sweet drink).', 'Check again after 15 minutes; repeat if still shaky.', 'Then eat a proper meal.'],
    esc: 'Confusion, drowsiness or not improving after two doses: tell the Crew Medical Officer now.', src: ['food'] },
  { id: 'MED-32', cat: 'medical', title: 'Dehydration', q: 'dehydrated dehydration thirsty dry mouth dark urine deshidratado deshidratacion sed boca seca orina oscura',
    a: 'In weightlessness thirst is weaker, so many crew drink less than they need.',
    steps: ['Drink a pouch now and one every hour until your urine is pale.', 'Add an electrolyte packet if you sweated or had diarrhoea.', 'Log your fluid intake today.'],
    esc: 'Dizziness when moving, confusion, or very little urine for a day: tell the Crew Medical Officer.', src: ['renal', 'food'] },
  { id: 'MED-33', cat: 'medical', title: 'Mild allergic reaction', q: 'allergy allergic reaction mild hives itchy eyes sneezing alergia leve reaccion alergica ronchas estornudos ojos llorosos',
    a: 'Itchy skin, hives or sneezing without breathing problems is usually mild.',
    steps: ['Move away from what triggered it, if you know.', 'Antihistamine only through the medication check (it applies your allergies).', 'Record the trigger in your medical profile.'],
    esc: 'Swelling of the lips, tongue or throat, wheezing or dizziness: emergency — press Help (severe allergic reaction).', src: ['immune'], emg: 'allergy' },
  { id: 'MED-34', cat: 'medical', title: 'Menstrual pain', q: 'menstrual pain period cramps menstruation colicos menstruales regla dolor de regla menstruacion periodo',
    a: 'Many crew suppress menstruation for flight; when it happens, cramps are managed as on Earth.',
    steps: ['Apply warmth (a warm pack) to the lower belly.', 'Gentle movement and stretching help.', 'Pain relief only through the medication check.', 'Make sure hygiene supplies are stocked.'],
    esc: 'Pain much worse than usual, very heavy bleeding, or pain with fever: tell the Crew Medical Officer.', src: ['med'] },
  { id: 'MED-35', cat: 'medical', title: 'Hiccups', q: 'hiccups hiccup hipo',
    a: 'Harmless and usually short. Eating fast or swallowing air makes them more likely.',
    steps: ['Hold your breath for 10 seconds, then breathe slowly.', 'Sip cold water slowly.'],
    esc: 'Hiccups lasting more than 48 hours: tell the Crew Medical Officer.', src: ['med'] },
  { id: 'MED-36', cat: 'medical', title: 'Loss of appetite', q: 'no appetite loss of appetite not hungry eating less food tastes bland no tengo hambre sin apetito falta de apetito no quiero comer',
    a: 'Food often tastes bland in space (blocked nose from the fluid shift), and stress lowers appetite. Eating too little costs muscle and bone.',
    steps: ['Eat small portions more often.', 'Use spicier menu items and condiments.', 'Log your body mass weekly.'],
    esc: 'Losing more than 3% of body mass, or not eating for 2 days: tell the Crew Medical Officer.', src: ['food'] },
  { id: 'WB-11', cat: 'wellbeing', title: 'Anger and irritability', q: 'angry anger irritable irritability short temper rage enojado enojo irritable rabia mal humor molesto',
    a: 'Irritability is one of the first signs of poor sleep, stress and confinement — not a character flaw.',
    steps: ['Step away for 10 minutes before you answer.', 'Check your sleep and workload in the last few days.', 'Talk about the issue later, in private, with "I" statements.'],
    esc: 'If you feel close to hurting someone or yourself, tell the Crew Medical Officer or commander now.', src: ['team', 'bmed'] },
  { id: 'WB-12', cat: 'wellbeing', title: 'Loneliness', q: 'lonely loneliness alone isolated nobody to talk solo soledad aislado nadie con quien hablar me siento solo',
    a: 'You can feel lonely even in a crew. It is common on long missions and gets better with small, regular contact.',
    steps: ['Share a meal with the crew today.', 'Schedule a call or message with someone at home.', 'Tell one crewmate how you feel.'],
    esc: 'If loneliness lasts weeks or comes with hopelessness, request a private psychological conference.', src: ['team', 'bmed'] },
  { id: 'WB-13', cat: 'wellbeing', title: 'Burnout', q: 'burnout burned out burnt out exhausted overwork no energy quemado agotado del trabajo sobrecarga burnout exhausto',
    a: 'Long stretches of work without recovery lead to exhaustion, cynicism and mistakes.',
    steps: ['Tell the commander which tasks can move; protect one rest period a day.', 'Keep sleep and exercise even when busy.', 'Do one thing just for you every day.'],
    esc: 'If you are making errors on safety-critical tasks, tell the commander now so work can be shared.', src: ['sleep', 'bmed'] },
  { id: 'WB-14', cat: 'wellbeing', title: 'Trouble concentrating ("space fog")', q: 'concentrate concentration focus forgetful memory brain fog slow thinking no me puedo concentrar concentracion olvido memoria niebla mental',
    a: 'Short sleep, CO₂, stress and the first weeks of adaptation all slow thinking.',
    steps: ['Check cabin CO₂ and last night\'s sleep.', 'Use checklists and ask a crewmate to cross-check critical steps.', 'Take short breaks every hour.'],
    esc: 'Sudden confusion, trouble speaking or one-sided weakness is an emergency: press Help.', src: ['bmed', 'sleep'] },
  { id: 'WB-15', cat: 'wellbeing', title: 'Nightmares or distressing memories after an emergency', q: 'nightmares bad dreams flashbacks trauma distressing memories after emergency pesadillas malos suenos recuerdos trauma',
    a: 'After a frightening event, nightmares and replaying it in your mind are common in the first weeks.',
    steps: ['Talk about what happened with the crew in a short debrief.', 'Keep your sleep routine; avoid screens before sleep.', 'Write down what you remember — it helps the mind file it.'],
    esc: 'If it lasts more than a month or affects your work, request a private psychological conference.', src: ['bmed', 'sleep'] },
  { id: 'WB-16', cat: 'wellbeing', title: 'Thoughts of hurting yourself', q: 'suicide suicidal kill myself end my life self harm hurt myself suicidio matarme quitarme la vida hacerme dano no quiero vivir',
    a: 'If you are having thoughts of hurting yourself, you are not alone and this can get better. It is a medical emergency, not a weakness.',
    steps: ['Tell a crewmate or the Crew Medical Officer right now — do not stay alone.', 'Ask for a private conference with the flight psychologist today.', 'Keep away from medicines and tools that could hurt you until you have talked to someone.'],
    esc: 'This is urgent: press Help now so a crewmate comes to you.', src: ['bmed'], emg: 'psych' },
  { id: 'WB-17', cat: 'wellbeing', title: 'Low motivation', q: 'no motivation unmotivated apathy dont care falta de motivacion desmotivado sin ganas apatia',
    a: 'Motivation often dips in the middle of a long mission — the "third quarter" effect.',
    steps: ['Set one small goal for today and finish it.', 'Plan something to look forward to this week.', 'Check sleep and mood — low motivation can be a sign of low mood.'],
    esc: 'If it comes with sadness, hopelessness or poor sleep for two weeks, request a private psychological conference.', src: ['bmed', 'team'] },

  /* ---------- more medical (v1.1) ---------- */
  { id: 'MED-37', cat: 'medical', title: 'Migraine', q: 'migraine migraines migrana migranas jaqueca aura throbbing pulsating one side light sensitivity zigzag lights pulsatil punzante luz molesta un lado lucecitas',
    a: 'A migraine is a throbbing headache, often on one side, with sensitivity to light and noise and sometimes nausea or an "aura" (zigzag lights) before it. In flight, short sleep, skipped meals, dehydration, stress, high CO₂ and screens are common triggers.',
    steps: ['Rest in a dark, quiet sleep station with an eye mask and earplugs.', 'Drink 250–500 mL of water and eat something if you skipped a meal.', 'Cold pack on the forehead or neck for 15 minutes.', 'Take pain relief early — through the medication check ("Can I take paracetamol?").', 'Log the time, sleep, meals and cabin CO₂ to find your triggers.'],
    esc: 'First migraine of your life, worst headache ever, an aura lasting more than 1 hour, weakness, numbness, trouble speaking, fever with a stiff neck, or a headache after a bump to the head: press Help and tell the Crew Medical Officer now.', src: ['sans', 'sleep', 'std2'] },
  { id: 'MED-38', cat: 'medical', title: 'Bump or blow to the head', q: 'head injury hit my head bump on the head concussion knocked head golpe en la cabeza me pegue en la cabeza contusion conmocion chichon',
    a: 'In microgravity it is easy to hit your head on hatches and equipment. Most bumps are minor, but a concussion can show up hours later.',
    steps: ['Stop and rest; a crewmate should stay with you for the next hours.', 'Cold pack on the bump for 15 minutes.', 'Check for headache, nausea, confusion, blurred vision or memory gaps.', 'No safety-critical tasks or EVA for 24 h.'],
    esc: 'Loss of consciousness, vomiting, worsening headache, confusion, unequal pupils, seizure, clear fluid from the nose or ears, or unusual sleepiness: emergency — press Help ("Head injury").', src: ['med'], emg: 'head' },
  { id: 'MED-39', cat: 'medical', title: 'Seizure (convulsion)', q: 'seizure convulsion fit epilepsy shaking jerking convulsion convulsiones ataque epileptico epilepsia temblores',
    a: 'During a seizure the priority is to protect the person from injury; it usually stops by itself within 1–2 minutes.',
    steps: ['Do not hold them down and put nothing in their mouth.', 'Move hard objects away; in microgravity, loosely restrain them to a soft surface.', 'Time the seizure.', 'Afterwards, put them on their side and stay with them.'],
    esc: 'A seizure lasting more than 5 minutes, a second seizure, breathing problems or a first-ever seizure: emergency — press Help.', src: ['med'], emg: 'head' },
  { id: 'MED-40', cat: 'medical', title: 'Asthma or wheezing', q: 'asthma asthma attack wheeze wheezing inhaler tight chest asma ataque de asma silbido en el pecho inhalador pecho apretado',
    a: 'Dust, cabin chemicals or an infection can trigger asthma. Floating particles reach the airways more easily in microgravity.',
    steps: ['Sit upright and breathe slowly through pursed lips.', 'Use your prescribed inhaler (check it with the medication check if it is not in your profile).', 'Measure SpO₂.', 'Move away from dust or fumes.'],
    esc: 'No relief from the inhaler, trouble speaking, blue lips or SpO₂ under 92%: emergency — press Help ("Trouble breathing").', src: ['hypoxia', 'dust'], emg: 'breathing' },
  { id: 'MED-41', cat: 'medical', title: 'Choking', q: 'choking choke food stuck swallowed wrong cant swallow atragantado ahogado comida atorada me atragante no puedo tragar',
    a: 'If the person can cough or speak, the airway is partly open — let them cough.',
    steps: ['Encourage strong coughing.', 'If they cannot cough, speak or breathe: 5 back blows, then 5 abdominal thrusts (brace against a wall in microgravity).', 'Repeat until it clears or they become unresponsive.'],
    esc: 'If they become unresponsive: start CPR and press Help ("Unresponsive").', src: ['med'], emg: 'breathing' },
  { id: 'MED-42', cat: 'medical', title: 'Dry, tired or strained eyes', q: 'dry eyes tired eyes eye strain screens burning eyes ojos secos ojos cansados vista cansada ardor de ojos pantallas',
    a: 'Dry cabin air, floating dust and long screen work dry the eyes.',
    steps: ['Use lubricating eye drops from the medical kit.', 'Follow 20-20-20: every 20 minutes look at something far away for 20 seconds.', 'Blink fully and lower screen brightness.'],
    esc: 'Pain, sudden vision change or a red eye that does not improve in 2 days: tell the Crew Medical Officer.', src: ['sans', 'std2'] },
  { id: 'MED-43', cat: 'medical', title: 'Red, sticky eye or stye', q: 'pink eye conjunctivitis red eye sticky discharge stye eyelid bump conjuntivitis ojo rojo lagana orzuelo parpado',
    a: 'A red eye with discharge is usually an infection; a stye is a small painful bump on the eyelid.',
    steps: ['Do not rub or touch; wash hands often.', 'Warm compress for 10 minutes, 3–4 times a day (stye).', 'Use your own towel and wipes; no contact lenses until it clears.'],
    esc: 'Eye pain, light sensitivity, blurred vision or no improvement in 3 days: tell the Crew Medical Officer.', src: ['micro', 'immune'] },
  { id: 'MED-44', cat: 'medical', title: 'Mouth ulcers, cold sores or bleeding gums', q: 'mouth ulcer canker sore cold sore herpes lip blister bleeding gums aftas llaga en la boca fuego labial herpes encias sangran',
    a: 'Stress and changes in the immune system make mouth sores and cold sores more frequent in flight.',
    steps: ['Rinse with salt water after meals.', 'Avoid spicy, acidic food until it heals.', 'Brush gently with a soft brush and floss daily.', 'Cold sores: do not share cups and wash hands after touching.'],
    esc: 'A sore lasting more than 2 weeks, fever, or swelling of the face or jaw: tell the Crew Medical Officer.', src: ['immune', 'med'] },
  { id: 'MED-45', cat: 'medical', title: 'Neck pain or stiff neck', q: 'neck pain stiff neck neck ache torticollis dolor de cuello cuello rigido torticolis nuca',
    a: 'Holding the head in odd positions while working or sleeping in microgravity often strains the neck.',
    steps: ['Gentle neck rolls and shoulder shrugs, several times a day.', 'Warm pack for 15 minutes.', 'Adjust your sleep restraint and workstation height.'],
    esc: 'Stiff neck with fever and headache, or neck pain with arm numbness or weakness: tell the Crew Medical Officer now.', src: ['fit'] },
  { id: 'MED-46', cat: 'medical', title: 'Hand or fingernail injury after EVA', q: 'fingernail nail lifting glove hand pain fingertips eva gloves una una levantada guantes dolor de manos yemas de los dedos',
    a: 'Pressurised EVA gloves can bruise fingertips and lift fingernails (delamination).',
    steps: ['Keep nails short before every EVA.', 'Clean and cover a lifted nail; keep it dry.', 'Report glove fit problems so they can be adjusted.'],
    esc: 'Signs of infection (redness, pus, throbbing) or numbness lasting more than a day: tell the Crew Medical Officer.', src: ['dcs', 'med'] },
  { id: 'MED-47', cat: 'medical', title: 'Swollen arm, leg or neck (clot warning)', q: 'swollen leg swollen arm calf pain clot thrombosis neck swelling dvt pierna hinchada brazo hinchado coagulo trombosis pantorrilla cuello hinchado',
    a: 'Blood clots have been found in the neck veins of some astronauts. One-sided swelling, pain or warmth in a limb or the neck needs checking.',
    steps: ['Do not massage the area.', 'Measure heart rate and SpO₂.', 'Note which side, since when, and compare with the other side.'],
    esc: 'Swelling with sudden breathlessness or chest pain: emergency — press Help. Any one-sided swelling: tell the Crew Medical Officer today (ultrasound exam).', src: ['cv', 'med'] },
  { id: 'MED-48', cat: 'medical', title: 'Trouble passing urine', q: 'cant pee cannot urinate trouble urinating urinary retention weak stream no puedo orinar me cuesta orinar retencion de orina chorro debil',
    a: 'In the first days of flight the bladder does not feel full the same way, so some crew have trouble starting to urinate.',
    steps: ['Urinate on a schedule, every 2–3 hours, even without the urge.', 'Relax, take your time and use the airflow of the toilet as designed.', 'Log fluid intake.'],
    esc: 'No urine for 8 hours, lower belly pain or swelling: tell the Crew Medical Officer now — a catheter may be needed.', src: ['renal', 'med'] },
  { id: 'MED-49', cat: 'medical', title: 'Haemorrhoids or anal pain', q: 'hemorrhoids haemorrhoids piles anal pain itching bleeding when pooping hemorroides almorranas dolor anal picazon sangrado al defecar',
    a: 'Constipation and straining make haemorrhoids more likely.',
    steps: ['Prevent constipation: 2 L of fluid a day and high-fibre food.', 'Do not strain; keep the area clean and dry.', 'Soothing cream only through the medication check.'],
    esc: 'Heavy bleeding, black stools, or severe pain: tell the Crew Medical Officer.', src: ['food'] },
  { id: 'MED-50', cat: 'medical', title: 'Fungal infection (feet, groin, skin folds)', q: 'athletes foot fungus fungal infection itchy groin itchy feet ringworm pie de atleta hongos picazon en la ingle pies con picazon tina',
    a: 'Warm, damp clothing and the lack of showers help fungi grow on the feet and in skin folds.',
    steps: ['Keep the area clean and fully dry.', 'Change socks and underwear daily.', 'Antifungal cream only through the medication check.'],
    esc: 'Spreading redness, pain, oozing or fever: tell the Crew Medical Officer.', src: ['micro'] },
  { id: 'MED-51', cat: 'medical', title: 'Peeling feet or soft calluses', q: 'peeling feet calluses soles skin peeling feet baby feet pies pelados callos piel de los pies se pela',
    a: 'Without walking, the soles lose their hard skin, which peels off and floats.',
    steps: ['Remove loose skin over a wipe or in socks so flakes do not float.', 'Moisturise the feet daily.', 'Expect tender soles after landing.'],
    esc: 'Cracks that bleed, redness or pus: tell the Crew Medical Officer.', src: ['std2'] },
  { id: 'MED-52', cat: 'medical', title: 'Vertigo — the room is spinning', q: 'vertigo spinning room spinning dizzy spinning balance vertigo todo me da vueltas la habitacion gira equilibrio',
    a: 'The inner ear adapts to weightlessness and again to gravity; brief spinning with head movement is common in those days.',
    steps: ['Keep your head still and fix your eyes on one point.', 'Move your head slowly; avoid fast turns.', 'Hold on with a hand or foot restraint.'],
    esc: 'Spinning with a severe headache, double vision, weakness, slurred speech, hearing loss or vomiting that does not stop: press Help.', src: ['sensori'] },
  { id: 'MED-53', cat: 'medical', title: 'High blood sugar or diabetes', q: 'diabetes high blood sugar hyperglycemia insulin thirsty peeing a lot azucar alta glucosa alta diabetes hiperglucemia insulina mucha sed orino mucho',
    a: 'Spaceflight can lower insulin sensitivity. Very high sugar causes thirst, frequent urination and tiredness.',
    steps: ['Measure fasting blood glucose and log it.', 'Drink water; avoid sweet drinks.', 'Keep exercise and meals regular.'],
    esc: 'Glucose above 250 mg/dL, vomiting, confusion or fruity-smelling breath: tell the Crew Medical Officer now.', src: ['food', 'med'] },
  { id: 'MED-54', cat: 'medical', title: 'Pale, tired and short of breath on effort (anaemia)', q: 'anemia anaemia pale low iron low hemoglobin weak tired anemia palido hierro bajo hemoglobina baja debil',
    a: 'In space the body destroys more red blood cells ("space anaemia"), which can cause tiredness and breathlessness on effort.',
    steps: ['Log fatigue and heart rate during exercise.', 'Eat the full menu, including iron and protein.', 'Ask for a blood count at the next medical conference.'],
    esc: 'Fainting, chest pain, black stools or breathlessness at rest: tell the Crew Medical Officer now.', src: ['immune', 'food'] },
  { id: 'MED-55', cat: 'medical', title: 'Weight loss or weight gain', q: 'weight loss losing weight weight gain getting fat body mass bajar de peso perdi peso subir de peso engorde masa corporal',
    a: 'Most crew lose weight in flight because they eat less than they burn; that costs muscle and bone.',
    steps: ['Log body mass every week.', 'Eat all meal packs and snacks on the menu.', 'Keep the exercise prescription.'],
    esc: 'Loss of more than 5% of body mass, or a sudden change without a reason: tell the Crew Medical Officer.', src: ['food', 'fit'] },
  { id: 'MED-56', cat: 'medical', title: 'Overheating or heat exhaustion', q: 'overheating heat exhaustion too hot in the suit sweating a lot hot flushed calor agotamiento por calor sudor mucho calor en el traje acalorado',
    a: 'Heat builds up during hard work, exercise or in a suit with poor cooling.',
    steps: ['Stop the activity and move to a cooler module.', 'Drink a pouch with electrolytes.', 'Cool the neck and armpits with wet cloths; increase airflow.'],
    esc: 'Temperature 39 °C or more, confusion, fainting or no sweating: emergency — press Help.', src: ['std2', 'fit'] },
  { id: 'MED-57', cat: 'medical', title: 'Swallowed or inhaled a chemical', q: 'poison poisoning swallowed chemical inhaled fumes ingested intoxicado envenenado trague quimico inhale vapores intoxicacion',
    a: 'Act fast and identify the product.',
    steps: ['Do not make the person vomit.', 'Move to clean air; mask on if fumes are present.', 'Rinse the mouth; keep the label or the name of the product.', 'Measure SpO₂ and heart rate.'],
    esc: 'Any breathing trouble, drowsiness or burns in the mouth: emergency — press Help ("Smoke or toxic gas").', src: ['std2'], emg: 'toxic' },
  { id: 'MED-58', cat: 'medical', title: 'Electric shock', q: 'electric shock electrocuted shocked by equipment descarga electrica electrocutado me dio corriente choque electrico',
    a: 'Even a shock that seems small can disturb the heart rhythm.',
    steps: ['Cut the power before touching the person.', 'Check breathing and pulse.', 'Look for burns where the current entered and left.', 'Record an ECG if available.'],
    esc: 'Unresponsive, irregular heartbeat, chest pain or burns: emergency — press Help.', src: ['cv', 'std2'], emg: 'unresponsive' },
  { id: 'MED-59', cat: 'medical', title: 'Vomiting blood or black stools', q: 'vomiting blood black stool tarry stool blood in vomit vomito con sangre heces negras popo negro sangre en el vomito',
    a: 'This can be bleeding in the stomach or gut and must be checked the same day.',
    steps: ['Stop all activity and rest.', 'Measure blood pressure, heart rate and SpO₂.', 'Do not take aspirin or ibuprofen.'],
    esc: 'Tell the Crew Medical Officer now; with dizziness or fainting press Help ("Severe bleeding").', src: ['med'], emg: 'bleeding' },
  { id: 'MED-60', cat: 'medical', title: 'Severe or constant belly pain', q: 'severe belly pain severe abdominal pain appendicitis lower right pain stomach very hard dolor fuerte de estomago dolor abdominal fuerte apendicitis lado derecho abajo',
    a: 'Severe, constant belly pain — especially low on the right, with fever or vomiting — may be appendicitis or another serious problem.',
    steps: ['Do not eat; small sips of water only.', 'Measure temperature, heart rate and blood pressure.', 'Note where the pain started and where it is now.'],
    esc: 'Tell the Crew Medical Officer now — an ultrasound exam and a call to ground are needed.', src: ['med'] },
  { id: 'MED-61', cat: 'medical', title: 'Jaw pain or teeth grinding', q: 'jaw pain teeth grinding clenching bruxism tmj dolor de mandibula rechinar los dientes apretar los dientes bruxismo',
    a: 'Stress and sleep problems make people clench or grind their teeth, usually at night.',
    steps: ['Relax the jaw: lips together, teeth apart.', 'Warm pack on the jaw muscles for 10 minutes.', 'Use a mouth guard at night if one is in the dental kit.'],
    esc: 'Jaw pain with chest pain or breathlessness: press Help (it can be the heart).', src: ['bmed', 'med'] },
  { id: 'MED-62', cat: 'medical', title: 'Bruises that appear easily', q: 'bruise bruising easily purple marks moreton moretones hematoma morado',
    a: 'Bumping into equipment is common; most bruises fade in 1–2 weeks.',
    steps: ['Cold pack for the first day, warm after that.', 'Note where and how it happened.'],
    esc: 'Bruises without a bump, with bleeding gums or nosebleeds, or if you take a blood thinner: tell the Crew Medical Officer.', src: ['med'] },
  { id: 'MED-63', cat: 'medical', title: 'Side effects of a medicine', q: 'side effect side effects reaction to medicine bad reaction pill made me feel efecto secundario efectos secundarios reaccion al medicamento me cayo mal la pastilla',
    a: 'Medicines can behave differently in space. Any new symptom after starting one should be recorded.',
    steps: ['Write down the medicine, dose, time and the symptom.', 'Do not take another dose until you have checked it with the medication check.', 'Record the reaction in your medical profile.'],
    esc: 'Rash with swelling, breathing trouble or fainting: emergency — press Help ("Severe allergic reaction").', src: ['pharm'], emg: 'allergy' },
  { id: 'MED-64', cat: 'medical', title: 'Itchy scalp, dandruff or greasy hair', q: 'itchy scalp dandruff greasy hair hair loss wash hair picazon cuero cabelludo caspa pelo grasoso caida del pelo lavar el pelo',
    a: 'Without showers, oil and skin flakes build up on the scalp.',
    steps: ['Use no-rinse shampoo and a towel every 2–3 days.', 'Comb over a vacuum or wipe so hair and flakes do not float.'],
    esc: 'Red, painful or oozing patches: tell the Crew Medical Officer.', src: ['std2'] },

  /* ---------- more emotional wellbeing (v1.1) ---------- */
  { id: 'WB-18', cat: 'wellbeing', title: 'Feeling trapped or closed in (claustrophobia)', q: 'claustrophobia trapped closed in confined small space no way out claustrofobia encerrado atrapado espacio pequeno sin salida',
    a: 'Living in a small space for months can trigger the feeling of being trapped, even in people who never felt it before.',
    steps: ['Go to the largest module or a window and look far away (Earth or stars).', 'Slow breathing: in for 4, out for 6.', 'Plan time alone each day in your own sleep station.'],
    esc: 'If it causes panic attacks or stops you working: request a private psychological conference.', src: ['bmed', 'std2'] },
  { id: 'WB-19', cat: 'wellbeing', title: 'Guilt or shame after a mistake', q: 'guilt guilty shame ashamed made a mistake my fault failed culpa culpable verguenza me equivoque cometi un error fue mi culpa falle',
    a: 'Everyone makes mistakes on long missions. What matters is reporting it, learning and moving on — a calm crew is safer than a perfect one.',
    steps: ['Report the mistake plainly so it can be fixed.', 'Separate what happened from who you are.', 'Write one thing you will do differently next time.', 'Talk to a crewmate you trust.'],
    esc: 'If guilt keeps you awake for days or comes with thoughts of hurting yourself: tell the Crew Medical Officer today.', src: ['bmed', 'team'] },
  { id: 'WB-20', cat: 'wellbeing', title: 'Low self-confidence or feeling not good enough', q: 'low self esteem self confidence not good enough impostor insecure inferior autoestima baja inseguridad inseguro no soy suficiente impostor no sirvo',
    a: 'Being surrounded by highly trained people can make anyone doubt themselves. You were selected because you are capable.',
    steps: ['Write three things you did well this week.', 'Ask for feedback on one concrete task.', 'Compare yourself with your own progress, not with others.'],
    esc: 'If it comes with persistent sadness or hopelessness, see "Feeling sad" and request a psychological conference.', src: ['bmed'] },
  { id: 'WB-21', cat: 'wellbeing', title: 'Overthinking, worrying or intrusive thoughts', q: 'overthinking worry worrying intrusive thoughts obsessive thoughts cant stop thinking rumination pienso demasiado pensamientos intrusivos pensamientos obsesivos no paro de pensar preocupacion darle vueltas',
    a: 'In a quiet, closed environment the mind tends to replay worries. A thought is not a fact and does not have to be acted on.',
    steps: ['Set a 15-minute "worry time" each day and write the worries down.', 'When a thought loops, name it ("this is a worry") and return to what you are doing.', 'Exercise and slow breathing lower the volume of worry.'],
    esc: 'If thoughts are frightening, violent, or you cannot control them: request a private psychological conference today.', src: ['bmed'] },
  { id: 'WB-22', cat: 'wellbeing', title: 'Mood swings', q: 'mood swings emotional ups and downs moody emotional cambios de humor cambios de animo emocional altibajos',
    a: 'Sleep loss, stress and confinement make emotions stronger and faster to change.',
    steps: ['Log your mood twice a day for a week to see the pattern.', 'Protect your sleep window.', 'Name the emotion before you react to it.'],
    esc: 'Days of very high energy with little sleep, or swings that affect safety: tell the Crew Medical Officer.', src: ['bmed', 'sleep'] },
  { id: 'WB-23', cat: 'wellbeing', title: 'Fear that something bad will happen', q: 'fear of dying afraid of dying scared something will go wrong fear of death worried about health miedo a morir miedo a la muerte miedo a que algo salga mal preocupado por mi salud',
    a: 'Thinking about the risks of the mission is natural. The crew, the procedures and NovaCare exist to handle those risks.',
    steps: ['Talk about the fear with a crewmate or the flight psychologist.', 'Review the procedure for the situation you fear — knowing the plan reduces fear.', 'Focus on what you can control today.'],
    esc: 'If the fear is constant, causes panic or stops you sleeping: request a private psychological conference.', src: ['bmed'] },
  { id: 'WB-24', cat: 'wellbeing', title: 'Problems with partner or family at home', q: 'relationship problems partner wife husband girlfriend boyfriend kids family problems divorce problemas de pareja esposa esposo novia novio hijos problemas familiares divorcio',
    a: 'Being far away makes it hard to help with problems at home, and that feeling of helplessness is very stressful.',
    steps: ['Schedule a private call with time to talk calmly.', 'Ask the family support office on the ground to help at home.', 'Write down what you want to say before the call.'],
    esc: 'If it stops you sleeping or concentrating: request a private psychological conference.', src: ['bmed', 'team'] },
  { id: 'WB-25', cat: 'wellbeing', title: 'Feeling left out by the crew', q: 'left out excluded ignored crew doesnt like me no friends rejected me excluyen me ignoran no le caigo bien a nadie rechazado excluido',
    a: 'Sub-groups form in every crew. Feeling left out is common and can be fixed with small steps.',
    steps: ['Join one shared meal or activity today.', 'Ask a crewmate for help or offer yours.', 'Tell the commander privately if it continues.'],
    esc: 'If it comes with sadness or isolation for weeks: request a psychological conference.', src: ['team'] },
  { id: 'WB-26', cat: 'wellbeing', title: 'Feeling unreal, or seeing or hearing things', q: 'feel unreal detached derealization depersonalization hearing voices seeing things hallucination me siento irreal desconectado oigo voces veo cosas alucinacion',
    a: 'Extreme tiredness and stress can make the world feel unreal. Hearing or seeing things others do not is a medical issue that needs checking.',
    steps: ['Ground yourself: touch something cold, name 5 things you see.', 'Sleep and eat — exhaustion is a common cause.', 'Tell a crewmate what you are experiencing.'],
    esc: 'Voices, visions or strong beliefs others do not share: tell the Crew Medical Officer today.', src: ['bmed', 'sleep'] },
  { id: 'WB-27', cat: 'wellbeing', title: 'Emotional eating or not eating', q: 'emotional eating binge eating overeating not eating stress eating comer por ansiedad atracones como mucho no como comer emocional',
    a: 'Stress and boredom change appetite. In space, eating too little is the bigger risk to muscle and bone.',
    steps: ['Eat at fixed times with the crew.', 'Before eating outside meals, ask: am I hungry or stressed?', 'Log your meals and body mass.'],
    esc: 'Making yourself vomit, skipping meals on purpose, or large weight changes: tell the Crew Medical Officer.', src: ['food', 'bmed'] },
  { id: 'WB-28', cat: 'wellbeing', title: 'Cravings or withdrawal (caffeine, nicotine, alcohol)', q: 'craving withdrawal nicotine smoking cigarette caffeine coffee alcohol addiction antojo abstinencia nicotina fumar cigarro cafeina cafe alcohol adiccion',
    a: 'Withdrawal can cause irritability, headache and poor sleep for days or weeks.',
    steps: ['Expect the craving to peak and pass within 10–20 minutes.', 'Distract yourself: exercise, a task, a call.', 'Keep caffeine to the morning.'],
    esc: 'Shaking, sweating, confusion or seeing things (alcohol withdrawal): tell the Crew Medical Officer now.', src: ['bmed'] },
  { id: 'WB-29', cat: 'wellbeing', title: 'Pressure to perform or fear of failure', q: 'pressure to perform fear of failure perfectionism perfectionist performance anxiety presion miedo al fracaso perfeccionismo perfeccionista ansiedad de rendimiento',
    a: 'High standards help in a mission, but perfectionism increases stress and mistakes.',
    steps: ['Define "good enough" for each task before starting.', 'Use checklists and a crewmate check instead of worrying.', 'Celebrate tasks finished, not only perfect ones.'],
    esc: 'If fear of failure blocks you from tasks: talk to the commander or request a psychological conference.', src: ['bmed'] },
  { id: 'WB-30', cat: 'wellbeing', title: 'Worry about returning to Earth', q: 'returning to earth after the mission going home life after landing worry readaptation volver a la tierra despues de la mision regresar a casa adaptacion',
    a: 'Many astronauts feel unsure about going back: their body, work and family have changed. This is a normal transition.',
    steps: ['Plan the first weeks after landing with the support team.', 'Talk with family about expectations.', 'Keep exercise high — it makes physical recovery faster.'],
    esc: 'If worry affects sleep or mood: request a psychological conference.', src: ['bmed', 'fit'] },
  { id: 'WB-31', cat: 'wellbeing', title: 'Big feelings about Earth, life and meaning', q: 'overview effect meaning of life existential small universe looking at earth sentido de la vida existencial pequeno universo mirar la tierra',
    a: 'Seeing Earth from space often brings strong emotions and questions about life. Most astronauts describe it as positive.',
    steps: ['Write or record what you feel.', 'Share it with the crew or family.', 'Take time at the window — it can be a source of calm.'],
    esc: 'If the feelings become distressing or hopeless: see "Feeling sad".', src: ['bmed'] },
  { id: 'WB-32', cat: 'wellbeing', title: 'How to relax and calm down', q: 'relax relaxation calm down breathing exercise meditation mindfulness how to calm relajarme relajacion calmarme ejercicio de respiracion meditacion como me calmo tranquilizarme',
    a: 'Slow breathing and body relaxation lower heart rate and stress within minutes.',
    steps: ['Box breathing: in 4, hold 4, out 4, hold 4 — for 4 minutes.', 'Tense each muscle group for 5 seconds, then release, from feet to face.', '5 minutes of attention on your breath or on the view of Earth.'],
    esc: 'If you cannot calm down after 20 minutes, see "Anxiety or panic".', src: ['bmed'] },
  { id: 'WB-33', cat: 'wellbeing', title: 'Feeling overwhelmed — "I can’t take it anymore"', q: 'overwhelmed cant take it anymore breaking down too much falling apart no puedo mas ya no aguanto me estoy derrumbando colapso abrumado demasiado',
    a: 'Feeling overwhelmed means your load is bigger than your resources right now. That can change.',
    steps: ['Stop for 10 minutes; slow breathing.', 'Tell a crewmate now — you do not have to carry it alone.', 'Ask the commander to move non-critical tasks.'],
    esc: 'If you are thinking of hurting yourself: press Help now. Otherwise request a psychological conference today.', src: ['bmed', 'team'] },
  { id: 'WB-34', cat: 'wellbeing', title: 'Looking after your mental health', q: 'mental health psychological health how to feel better improve mood be happy wellbeing salud mental salud psicologica sentirme mejor mejorar el animo ser feliz bienestar',
    a: 'Mental health on a mission rests on the same basics every day: sleep, exercise, connection and meaning.',
    steps: ['Protect 8 hours of sleep and daily exercise.', 'One real conversation a day with the crew or home.', 'Do one thing for yourself every day.', 'Log mood and stress in your check-in so changes are caught early.'],
    esc: 'If you notice two weeks of low mood, anxiety or poor sleep: request a private psychological conference.', src: ['bmed', 'sleep', 'team'] },

  /* ---------- more medical and wellbeing (v1.2) ---------- */
  { id: 'MED-65', cat: 'medical', title: 'Gastritis', q: 'gastritis stomach lining inflamed burning upper belly gnawing gastritis ardor boca del estomago gastrite queimacao brulure',
    a: 'Gastritis is irritation of the stomach lining: a burning or gnawing pain in the upper belly, often with nausea or feeling full quickly. Stress, irregular meals, coffee, spicy food and some pain medicines (such as ibuprofen or aspirin) make it worse.',
    steps: ['Eat small, regular, bland meals; do not skip meals.', 'Cut down on coffee, spicy and acidic food until it settles.', 'Avoid ibuprofen and aspirin; any medicine, including antacids, only through the medication check.', 'Log the pain (0–10), when it comes and what you ate.'],
    esc: 'Vomiting blood, black stools, severe or constant pain, pain spreading to the back, or no improvement after 1 week: tell the Crew Medical Officer now.', src: ['food', 'med'] },
  { id: 'MED-66', cat: 'medical', title: 'Gas, flatulence and burping', q: 'gas wind flatulence fart farting passing gas burp burping belching gassy gases pedos flatulencia eructos eructar tirarse pedos muchos gases peidos arrotos arrotar gaz pets roter rots',
    a: 'Gas is normal, but in microgravity it does not rise and separate from food in the stomach, so crew often have more "wet burps" and wind. Swallowed air, fizzy drinks, beans, cabbage and some freeze-dried foods add to it.',
    steps: ['Eat slowly with your mouth closed; avoid gum and gulping drinks.', 'Cut down on fizzy drinks and foods that give you gas for a few days.', 'Move: exercise and gentle twisting help gas pass.', 'Keep the cabin ventilation running; the toilet fan helps with odour.'],
    esc: 'Gas with severe or constant pain, a hard swollen belly, vomiting, fever, blood in the stool, or no stool or wind for a day: tell the Crew Medical Officer now.', src: ['food'] },
  { id: 'MED-67', cat: 'medical', title: 'Stomach ulcer', q: 'ulcer stomach ulcer peptic ulcer duodenal pain on empty stomach ulcera ulcera gastrica ulcera peptica dolor con hambre ulcere gastrique',
    a: 'An ulcer is a sore in the lining of the stomach or the first part of the gut. It causes a burning pain in the upper belly, often when the stomach is empty or at night, that may ease after eating. Pain medicines such as ibuprofen and aspirin, and a stomach infection, are common causes.',
    steps: ['Do not take ibuprofen, aspirin or similar pain medicines; check any medicine with the medication check.', 'Eat small, regular meals; avoid coffee and very spicy food.', 'Log when the pain comes and whether food helps.', 'Ask for a medical conference — treatment is decided by the Crew Medical Officer and ground.'],
    esc: 'Vomiting blood or "coffee grounds", black stools, sudden severe belly pain, dizziness or fainting: press Help (possible bleeding).', src: ['med', 'pharm'], emg: 'bleeding' },
  { id: 'MED-68', cat: 'medical', title: 'Irritable bowel', q: 'irritable bowel ibs cramps diarrhea and constipation alternating bloating nervous stomach colon irritable intestino irritable colitis nerviosa sindrome intestino irritavel intestin irritable',
    a: 'Irritable bowel causes repeated belly cramps, bloating and changes in bowel habits (diarrhoea, constipation or both) without damage to the gut. Stress, irregular meals and some foods trigger it, and it often gets worse on a mission.',
    steps: ['Keep a food and symptom log for 2 weeks to find your triggers.', 'Eat at regular times, drink 2 L a day and add fibre slowly.', 'Use stress tools such as breathing and exercise — the gut and stress are linked.', 'Medicine only through the medication check.'],
    esc: 'Blood in the stool, weight loss, fever, waking at night with diarrhoea, or a new change in bowel habits: tell the Crew Medical Officer — these are not irritable bowel.', src: ['food', 'bmed'] },
  { id: 'MED-69', cat: 'medical', title: 'Lactose or food intolerance', q: 'lactose intolerance food intolerance dairy milk upsets stomach gluten food sensitivity intolerancia lactosa intolerancia alimentaria leche me cae mal lacteos leite intolerance lait',
    a: 'Food intolerance (for example to lactose in milk) causes bloating, gas, cramps or diarrhoea some hours after eating that food. It is not an allergy and is not dangerous, but it is uncomfortable.',
    steps: ['Note what you ate and when the symptoms started.', 'Avoid the suspected food for 2 weeks and see if the symptoms stop.', 'Ask ground to adjust your menu so you still get enough calcium and protein.', 'Record it in your medical profile.'],
    esc: 'Swelling of the lips or throat, hives, wheezing or dizziness after a food is an allergy, not an intolerance: press Help. Weight loss or blood in the stool: tell the Crew Medical Officer.', src: ['food'], emg: 'allergy' },
  { id: 'MED-70', cat: 'medical', title: 'Food poisoning', q: 'food poisoning bad food ate something bad spoiled food stomach bug vomiting and diarrhea intoxicacion alimentaria comida en mal estado comi algo malo intoxicacao alimentar intoxication alimentaire',
    a: 'Vomiting, diarrhoea and cramps a few hours after eating usually come from spoiled or contaminated food. Most cases settle in 1–2 days; the main risk is losing fluids. Others who ate the same food may get sick too.',
    steps: ['Sip fluids with an electrolyte packet often, even if you vomit.', 'Rest; eat small, bland portions once the vomiting stops.', 'Keep the rest of the food pack and tell the crew — check anyone who ate it.', 'Wash hands and clean the toilet area after use.'],
    esc: 'Blood in the stool or vomit, fever over 38.5 °C, unable to keep fluids down for 12 hours, confusion or very little urine: tell the Crew Medical Officer now.', src: ['food', 'micro'] },
  { id: 'MED-71', cat: 'medical', title: 'Vomiting', q: 'vomiting throwing up threw up puking cant stop vomiting vomitar vomitando devolver estoy vomitando vomitei vomir vomissement',
    a: 'Vomiting has many causes: a stomach bug, food, a medicine, a head injury or something serious in the belly. After the first days of flight it is not "just space sickness". In microgravity vomit floats and can be breathed in, so keep a bag ready.',
    steps: ['Keep an emesis bag at hand and clean up any floating droplets.', 'After vomiting, wait 30 minutes, then sip small amounts of fluid with electrolytes.', 'Log how many times, the colour and any other symptom (pain, fever, headache).', 'Anti-nausea medicine only through the medication check.'],
    esc: 'Blood or "coffee grounds", green vomit, severe belly pain, a recent bump to the head, a stiff neck, confusion, or vomiting for more than 24 h: tell the Crew Medical Officer now.', src: ['med', 'food'] },
  { id: 'MED-72', cat: 'medical', title: 'Hernia (bulge in the groin or belly)', q: 'hernia bulge groin lump belly button bulge inguinal umbilical bulto en la ingle bulto en el ombligo hernia inguinal hernie',
    a: 'A hernia is a soft bulge in the groin or belly where tissue pushes through a weak spot in the muscle. It is often more visible when you cough or strain and may go back in when you lie down. Heavy resistance exercise can make it worse.',
    steps: ['Avoid straining and heavy resistance exercise until it is checked.', 'Prevent constipation and support the area when you cough.', 'Note its size and whether it goes back in.', 'Tell the Crew Medical Officer at the next conference.'],
    esc: 'A bulge that becomes hard, painful or red, will not go back in, or comes with vomiting: emergency — tell the Crew Medical Officer now (trapped hernia).', src: ['med', 'fit'] },
  { id: 'MED-73', cat: 'medical', title: 'Gallbladder pain', q: 'gallbladder gallstones pain under right ribs pain after fatty food biliary colic vesicula biliar piedras en la vesicula calculos colica biliar vesicule',
    a: 'Gallstones can block the gallbladder and cause strong pain under the right ribs, often after a fatty meal, sometimes spreading to the right shoulder or back, with nausea. Losing weight fast makes stones more likely.',
    steps: ['Stop eating; small sips of water only.', 'Measure temperature and heart rate.', 'Note when the pain started, how long it lasts and where it spreads.', 'Pain relief only through the medication check.'],
    esc: 'Pain lasting more than 4–6 hours, fever, yellow skin or eyes, dark urine or pale stools: tell the Crew Medical Officer now — an ultrasound exam is needed.', src: ['med', 'food'] },
  { id: 'MED-74', cat: 'medical', title: 'Bronchitis', q: 'bronchitis phlegm mucus chest cold productive cough bronquitis flemas pecho cargado bronquite catarro bronchite',
    a: 'Bronchitis is inflammation of the airways, usually after a cold. It causes a cough with phlegm that can last 2–3 weeks, sometimes with a sore chest. Most cases are viral and get better without antibiotics.',
    steps: ['Log temperature and SpO₂ twice a day.', 'Drink warm fluids; breathe humidified air or steam if available.', 'Cough into a tissue or bag and throw it away — droplets float.', 'Cough medicine only through the medication check.'],
    esc: 'Fever over 38.5 °C for more than 2 days, breathlessness, SpO₂ under 94%, chest pain when breathing, or blood in the phlegm: tell the Crew Medical Officer today.', src: ['immune', 'micro'] },
  { id: 'MED-75', cat: 'medical', title: 'Pneumonia warning signs', q: 'pneumonia lung infection fever and cough breathing fast lungs neumonia pulmonia infeccion pulmonar pneumonia infeccao pulmonar pneumonie',
    a: 'Pneumonia is an infection of the lungs. Warning signs are fever, a cough with phlegm, fast or difficult breathing, pain on breathing in, and low oxygen. In a spacecraft it must be treated early.',
    steps: ['Measure SpO₂, temperature, heart rate and breathing rate.', 'Rest sitting up and drink fluids.', 'Wear a mask to protect the crew.', 'Tell the Crew Medical Officer today — antibiotics are decided by the CMO and ground.'],
    esc: 'SpO₂ under 92%, breathless at rest, confusion, blue lips or very fast breathing: emergency — press Help ("Trouble breathing").', src: ['immune', 'hypoxia'], emg: 'breathing' },
  { id: 'MED-76', cat: 'medical', title: 'Sinusitis', q: 'sinusitis sinus infection facial pain pressure behind the eyes thick green mucus sinus pressure dolor en la cara mocos verdes senos paranasales sinusite',
    a: 'Sinusitis is inflammation of the air spaces around the nose. It causes pressure or pain in the face, a blocked nose and thick yellow or green mucus. In space the fluid shift already blocks the nose, so a cold turns into sinusitis more easily. Most cases are viral.',
    steps: ['Saline nasal rinse or spray 2–3 times a day.', 'Warm compress over the cheeks and forehead.', 'Drink fluids and log your temperature.', 'Decongestants or other medicine only through the medication check.'],
    esc: 'Symptoms for more than 10 days, fever over 38.5 °C, swelling or redness around the eye, vision change, or a severe headache with a stiff neck: tell the Crew Medical Officer today.', src: ['sans', 'immune'] },
  { id: 'MED-77', cat: 'medical', title: 'Hay fever and allergic rhinitis', q: 'hay fever allergic rhinitis sneezing runny nose itchy nose watery eyes dust allergy rinitis alergica estornudos alergia al polvo moqueo rinite espirros rhinite allergique eternuements',
    a: 'Allergic rhinitis causes sneezing, a runny or itchy nose and watery eyes. A spacecraft has no pollen, but dust, floating particles and mould can trigger it.',
    steps: ['Saline nasal rinse to wash out particles.', 'Clean the filters and wipe dust at your sleep station; report mould.', 'Antihistamine only through the medication check.', 'Record the trigger in your medical profile.'],
    esc: 'Wheezing, shortness of breath or swelling of the face or throat: press Help ("Severe allergic reaction").', src: ['immune', 'dust'], emg: 'allergy' },
  { id: 'MED-78', cat: 'medical', title: 'Tonsillitis or throat infection', q: 'tonsillitis strep throat swollen tonsils white spots tonsils painful swallowing throat infection burning throat amigdalitis anginas placas en la garganta me arde la garganta dolor al tragar amigdalite angine amygdales',
    a: 'Tonsillitis is an infection of the tonsils: a painful throat, pain on swallowing, swollen red tonsils, sometimes with white spots, fever and swollen glands in the neck. Most cases are viral; some are bacterial (strep) and need antibiotics.',
    steps: ['Log your temperature and look at the throat with a light (take a photo for the CMO).', 'Drink warm or cold fluids and gargle with salt water.', 'Use your own cup and utensils and wash hands often.', 'Pain relief or antibiotics only through the medication check and the Crew Medical Officer.'],
    esc: 'Unable to swallow saliva, drooling, a muffled voice, trouble breathing, swelling on one side of the throat, or fever over 38.5 °C: tell the Crew Medical Officer now.', src: ['immune', 'micro'] },
  { id: 'MED-79', cat: 'medical', title: 'Hoarse voice or laryngitis', q: 'hoarse voice lost my voice laryngitis raspy voice no voice ronquera afonia afonico disfonia sin voz voz ronca laringitis rouquidao rouque extinction de voix laryngite',
    a: 'A hoarse voice usually comes from a cold, overusing the voice or dry cabin air. It normally recovers in 1–2 weeks.',
    steps: ['Rest your voice; do not whisper (it strains the voice more).', 'Drink often and breathe humidified air if available.', 'Avoid clearing your throat hard.'],
    esc: 'Hoarseness for more than 3 weeks, trouble breathing or swallowing, or coughing blood: tell the Crew Medical Officer.', src: ['immune', 'std2'] },
  { id: 'MED-80', cat: 'medical', title: 'Earwax or blocked ear', q: 'earwax ear wax blocked ear muffled hearing clogged ear plugged ear cera en el oido tapon de cera oido tapado cerilla cera no ouvido cerumen bouchon oreille',
    a: 'Earwax can build up and block the ear, especially when earplugs and headsets are worn every day. It causes muffled hearing, a full feeling and sometimes ringing.',
    steps: ['Do not use cotton buds — they push wax deeper.', 'Softening ear drops from the medical kit, only through the medication check.', 'Clean earplugs and headset pads regularly.'],
    esc: 'Ear pain, discharge, sudden hearing loss or dizziness: tell the Crew Medical Officer (see "Ear pain or ear pressure").', src: ['std2', 'med'] },
  { id: 'MED-81', cat: 'medical', title: 'Low blood pressure reading', q: 'low blood pressure hypotension low bp reading presion baja tension baja hipotension presion arterial baja pressao baixa hipotensao tension basse',
    a: 'A low reading (for example under 90/60) is often normal in fit people who feel well. It matters when it comes with dizziness, fainting, a fast pulse or cold, clammy skin. In flight, low fluid volume is a common cause.',
    steps: ['Lie down with your legs raised if you feel faint.', 'Drink 500 mL of water or an electrolyte drink.', 'Measure again after 10 minutes and log your heart rate too.', 'Check for bleeding, diarrhoea, fever or a new medicine.'],
    esc: 'Low pressure with fainting, confusion, chest pain, black stools, fever or a fast heart rate: tell the Crew Medical Officer now.', src: ['cv'] },
  { id: 'MED-82', cat: 'medical', title: 'Slow or fast heart rate reading', q: 'heart rate slow pulse fast pulse bradycardia tachycardia high heart rate low heart rate pulso lento pulso rapido taquicardia bradicardia frecuencia cardiaca pulsacoes frequence cardiaque',
    a: 'A resting heart rate of about 50 to 100 is usual; fit people may be lower. A fast rate often comes from exercise, stress, caffeine, fever or dehydration; a slow rate can be normal in athletes. What matters is the number at rest and how you feel.',
    steps: ['Rest for 5 minutes, then measure again, restrained and still.', 'Note caffeine, exercise, fever, stress or new medicines.', 'Check whether the rhythm feels regular.', 'Log it so the trend can be seen.'],
    esc: 'Over 120 or under 40 at rest, an irregular rhythm, or with chest pain, fainting or breathlessness: press Help ("Chest pain") and tell the Crew Medical Officer now.', src: ['cv'], emg: 'chest' },
  { id: 'MED-83', cat: 'medical', title: 'High cholesterol', q: 'high cholesterol cholesterol triglycerides blood fats lipids colesterol alto trigliceridos grasa en la sangre cholesterol',
    a: 'High cholesterol causes no symptoms; it raises the long-term risk of heart disease and stroke. Spaceflight and the diet may change blood fats, so they are checked in routine blood tests.',
    steps: ['Keep the daily exercise prescription.', 'Choose menu items with less saturated fat and more fibre.', 'Ask for your results at the next medical conference.'],
    esc: 'Chest pain, breathlessness or one-sided weakness: press Help. Cholesterol medicine is decided only by the Crew Medical Officer and ground.', src: ['cv', 'food'] },
  { id: 'MED-84', cat: 'medical', title: 'Stroke warning signs (FAST)', q: 'stroke fast face drooping arm weakness slurred speech one side weak cant talk derrame cerebral ictus embolia cara caida brazo debil habla arrastrada avc accident vasculaire cerebral',
    a: 'A stroke happens when blood flow to part of the brain stops. Use FAST: Face drooping, Arm weakness, Speech difficulty, Time to act. Other signs are sudden loss of vision, severe dizziness, confusion or a sudden, very severe headache. Every minute counts.',
    steps: ['Press Help now and note the exact time the symptoms started.', 'Keep the person still and restrained, with the head slightly raised.', 'Measure blood pressure, glucose and SpO₂ (low sugar can look like a stroke).', 'Give nothing by mouth.'],
    esc: 'Any FAST sign is an emergency even if it goes away: press Help and call the Crew Medical Officer now.', src: ['med', 'cv'], emg: 'head' },
  { id: 'MED-85', cat: 'medical', title: 'Heart attack warning signs', q: 'heart attack myocardial infarction crushing pressure pain in left arm jaw pain cold sweat infarto ataque al corazon ataque cardiaco brazo izquierdo opresion en el pecho crise cardiaque infarctus',
    a: 'Warning signs of a heart attack: pressure, tightness or pain in the chest lasting more than a few minutes, which may spread to the arm, jaw, neck or back, often with sweating, nausea or breathlessness. Signs can be milder or unusual, especially in women.',
    steps: ['Stop all activity and rest, restrained.', 'Press Help and open the "Chest pain" emergency protocol.', 'Measure blood pressure, heart rate and SpO₂; record an ECG if available.', 'Aspirin or any other medicine only through the emergency protocol and the medication check.'],
    esc: 'This is an emergency: press Help and call the Crew Medical Officer now.', src: ['cv'], emg: 'chest' },
  { id: 'MED-86', cat: 'medical', title: 'Tremor or shaking hands', q: 'tremor shaking hands trembling hands shaky hands hands shake tiemblan las manos temblor de manos tembleque maos tremendo tremor tremblement mains qui tremblent',
    a: 'A fine tremor of the hands often comes from caffeine, stress, tiredness, low blood sugar, some medicines or an overactive thyroid. It is usually harmless when it comes and goes.',
    steps: ['Look for triggers: caffeine, short sleep, skipped meals, a new medicine.', 'If you also feel sweaty or hungry, check your blood sugar or take fast sugar.', 'Note when it happens, which side, and whether it is at rest or when you move.'],
    esc: 'Tremor with confusion, fever, a fast heartbeat, one-sided weakness or trouble speaking, or a new tremor that keeps getting worse: tell the Crew Medical Officer now.', src: ['med', 'bmed'] },
  { id: 'MED-87', cat: 'medical', title: 'Fainting (passing out)', q: 'fainted fainting passed out blacked out lost consciousness syncope me desmaye desmayo perdi el conocimiento sincope desmaiei desmaio evanoui evanouissement',
    a: 'Fainting is a short loss of consciousness from a drop in blood flow to the brain. Common causes are standing up in gravity after flight, dehydration, heat, pain or the sight of blood. Some causes are in the heart, so every faint needs checking.',
    steps: ['Lay the person flat with the legs raised and check breathing.', 'When awake, keep them lying down for 10 minutes and give fluids.', 'Measure blood pressure, heart rate, glucose and SpO₂.', 'Check for injuries from the fall or collision.'],
    esc: 'Not waking within 1 minute, fainting during exercise, or with chest pain, palpitations, a seizure or a head injury: press Help ("Unresponsive").', src: ['cv'], emg: 'unresponsive' },
  { id: 'MED-88', cat: 'medical', title: 'Memory problems and forgetfulness', q: 'memory problems forgetting things forgetful cant remember memory loss mala memoria me olvido de todo perdida de memoria no me acuerdo esquecimento perda de memoria memoire oublis',
    a: 'Forgetting things is common with short sleep, stress, high CO₂, low mood and the heavy workload of a mission. It is usually temporary and improves with rest.',
    steps: ['Check the last nights\' sleep and the cabin CO₂.', 'Use checklists, notes and reminders; ask a crewmate to cross-check critical steps.', 'Do one thing at a time.', 'Log what you forgot and when, to show the pattern.'],
    esc: 'Sudden memory loss, confusion or trouble speaking, or forgetfulness after a bump to the head or an EVA: press Help.', src: ['bmed', 'sleep'], emg: 'head' },
  { id: 'MED-89', cat: 'medical', title: 'Tendinitis', q: 'tendinitis tendonitis tendon pain tennis elbow achilles overuse tendon inflamado codo de tenista dolor de tendon tendinite tendao',
    a: 'Tendinitis is irritation of a tendon from repeated movement or overload, for example on the exercise devices. It causes pain at the tendon that is worse with use, and stiffness in the morning.',
    steps: ['Reduce the movement that causes the pain, but do not stop exercising completely.', 'Cold pack (wrapped) for 15 minutes after use.', 'Ask for your exercise device settings and form to be checked.', 'Pain relief only through the medication check.'],
    esc: 'A sudden snap with loss of strength, large swelling, redness with fever, or no improvement after 2 weeks: tell the Crew Medical Officer.', src: ['fit'] },
  { id: 'MED-90', cat: 'medical', title: 'Carpal tunnel (numb hand and fingers)', q: 'carpal tunnel wrist numbness numb fingers tingling at night hand numb thumb tunel carpiano manos dormidas dedos dormidos tunel do carpo canal carpien',
    a: 'Carpal tunnel syndrome is pressure on a nerve at the wrist. It causes tingling, numbness or pain in the thumb and first fingers, often at night or after work with tools, keyboards or EVA gloves.',
    steps: ['Keep the wrist straight; avoid bending it for long periods.', 'Take breaks from gripping and typing and stretch the hands.', 'Wear a wrist splint at night if the medical kit has one.', 'Log the symptoms and which tasks trigger them.'],
    esc: 'Weak grip, dropping things, constant numbness, or numbness that starts suddenly or affects one whole side: tell the Crew Medical Officer.', src: ['fit', 'std2'] },
  { id: 'MED-91', cat: 'medical', title: 'Sciatica (pain down the leg)', q: 'sciatica pain down the leg sciatic nerve buttock pain shooting pain pinched nerve ciatica nervio ciatico dolor que baja por la pierna nalga sciatique',
    a: 'Sciatica is pain that runs from the lower back or buttock down the back of the leg, often with tingling. It comes from an irritated nerve root in the spine; in astronauts, disc problems are more common after returning to gravity.',
    steps: ['Keep gently active; avoid sitting or bending for long periods.', 'Heat on the lower back and buttock.', 'Gentle stretches for the back and the back of the thigh.', 'Pain relief only through the medication check.'],
    esc: 'Leg weakness, numbness in the groin, or trouble controlling bladder or bowel: emergency — tell the Crew Medical Officer now.', src: ['fit', 'bone'] },
  { id: 'MED-92', cat: 'medical', title: 'Heel or foot pain', q: 'heel pain foot pain plantar fasciitis sole pain arch pain first steps in the morning dolor de talon fascitis plantar planta del pie calcanhar fasciite talon',
    a: 'Heel and foot pain is common after returning to gravity, when the soles and the plantar fascia carry your weight again, and with treadmill running.',
    steps: ['Stretch the calf and the sole of the foot before standing up.', 'Wear cushioned, supportive shoes and increase walking or running slowly.', 'Roll the sole over a cold pouch for 10 minutes.'],
    esc: 'Severe pain after a jump or twist, swelling, being unable to put weight on it, or a red, hot foot: tell the Crew Medical Officer.', src: ['fit', 'bone'] },
  { id: 'MED-93', cat: 'medical', title: 'Sprained ankle', q: 'sprained ankle twisted ankle rolled ankle ankle sprain swollen ankle me torci el tobillo esguince de tobillo torcedura torci o tornozelo entorse cheville tordu',
    a: 'A sprain is a stretched or torn ligament, most often in the ankle after a twist. It is rare in flight but common after landing, while balance and muscles are still weak.',
    steps: ['Rest and keep weight off it for the first day.', 'Cold pack (wrapped) for 20 minutes every 2–3 hours.', 'Compression bandage and keep the foot raised.', 'Pain relief only through the medication check.'],
    esc: 'Unable to take 4 steps, pain on the bone, deformity, numbness or a cold foot: possible fracture — press Help ("Possible fracture or sprain").', src: ['bone', 'sensori'], emg: 'fracture' },
  { id: 'MED-94', cat: 'medical', title: 'Acne and pimples', q: 'acne pimples pimple spots zits blackheads grano granos espinillas barros puntos negros me salio un grano espinhas cravos bouton boutons',
    a: 'Pimples come from blocked, oily pores. In flight, no showers, sweaty clothing, helmets and stress can make them worse.',
    steps: ['Clean the skin twice a day with a gentle cleansing wipe.', 'Do not squeeze — it spreads infection and leaves marks.', 'Change pillow covers and clean helmet pads and headsets.', 'Creams only through the medication check.'],
    esc: 'A large, painful red swelling, spreading redness or fever: tell the Crew Medical Officer (see "Boil or abscess").', src: ['micro', 'std2'] },
  { id: 'MED-95', cat: 'medical', title: 'Eczema (dry, itchy patches)', q: 'eczema dermatitis dry itchy patches red scaly skin atopic eccema dermatitis piel reseca manchas rojas que pican dermatite',
    a: 'Eczema is dry, red, itchy and sometimes cracked skin, often on the elbows, knees, hands or face. Dry cabin air, soaps, sweat and stress make it flare up.',
    steps: ['Moisturise several times a day, right after washing.', 'Use gentle, fragrance-free wipes and soap.', 'Do not scratch; keep nails short and cover itchy areas at night.', 'Creams only through the medication check.'],
    esc: 'Weeping, crusting, pus, spreading redness, fever or painful blisters: possible infection — tell the Crew Medical Officer.', src: ['immune', 'std2'] },
  { id: 'MED-96', cat: 'medical', title: 'Psoriasis', q: 'psoriasis thick red scaly plaques silvery scales elbows knees scalp placas escamas plateadas psoriase',
    a: 'Psoriasis is a long-term skin condition with thick red patches covered in silvery scales, often on the elbows, knees and scalp. Stress, infections and dry air can trigger flares.',
    steps: ['Moisturise daily, especially after washing.', 'Remove loose scales over a wipe so the flakes do not float.', 'Continue your usual treatment; any medicine only through the medication check.', 'Log flares and possible triggers.'],
    esc: 'Painful, swollen joints, red skin over large areas, pus-filled spots or fever: tell the Crew Medical Officer.', src: ['immune'] },
  { id: 'MED-97', cat: 'medical', title: 'Warts', q: 'wart warts verruca plantar wart bump on finger verruga verrugas ojo de pescado verrue verrues',
    a: 'Warts are small, rough skin growths caused by a virus. They are harmless but can spread by touch or shared items.',
    steps: ['Do not pick or bite them.', 'Keep them covered and use your own towel, nail clippers and gloves.', 'Treatment only through the medication check.'],
    esc: 'A growth that bleeds, changes quickly, hurts, or is on the face or genitals: tell the Crew Medical Officer.', src: ['micro'] },
  { id: 'MED-98', cat: 'medical', title: 'Blisters', q: 'blister blisters friction rubbing shoe glove ampolla ampollas roce bolha bolhas ampoule ampoules',
    a: 'Blisters form where skin rubs, for example on the hands from tools and EVA gloves, or on the feet when you walk again after landing.',
    steps: ['Leave the blister intact if you can and cover it with a padded dressing.', 'If it bursts, clean it with saline and cover it; do not peel off the skin.', 'Fix the cause: gloves, socks, shoes or straps.'],
    esc: 'Spreading redness, pus, red streaks or fever: tell the Crew Medical Officer. Blisters from a burn: see "Burns".', src: ['med'] },
  { id: 'MED-99', cat: 'medical', title: 'Ingrown toenail', q: 'ingrown toenail toe nail digging in red swollen toe una encarnada una enterrada unero dedo del pie unha encravada ongle incarne',
    a: 'An ingrown toenail is the edge of a nail growing into the skin, usually on the big toe. It causes pain, redness and swelling, and can get infected.',
    steps: ['Soak the toe in warm water (or a warm wet wrap) for 10 minutes, 2–3 times a day.', 'Cut nails straight across, not too short.', 'Keep the area clean and dry and wear loose socks.'],
    esc: 'Pus, spreading redness, red streaks or fever: tell the Crew Medical Officer — it may need drainage.', src: ['micro'] },
  { id: 'MED-100', cat: 'medical', title: 'Boil or abscess', q: 'boil abscess pus painful red lump infected hair follicle forunculo absceso bola con pus nacido postema furunculo abscesso furoncle abces',
    a: 'A boil is an infected hair follicle; an abscess is a larger pocket of pus. Both are red, hot, painful lumps that may come to a head.',
    steps: ['Warm compress for 10 minutes, 3–4 times a day.', 'Do not squeeze or prick it.', 'Cover it, wash hands after touching it and use your own towel.', 'Mark the edge of the redness with a pen to see if it spreads.'],
    esc: 'Redness spreading past the mark, red streaks, fever, a boil on the face, or one larger than 2 cm: tell the Crew Medical Officer today — it may need drainage or antibiotics.', src: ['micro', 'immune'] },
  { id: 'MED-101', cat: 'medical', title: 'Hives (urticaria)', q: 'hives urticaria welts itchy bumps wheals raised rash ronchas habones ronchas que pican vergoes urticaire',
    a: 'Hives are raised, itchy welts that come and go within hours. Causes include allergies to food or medicines, infections, heat, pressure and stress; often no cause is found.',
    steps: ['Think of anything new: food, medicine, soap or fabric.', 'Use cool compresses and wear loose clothing.', 'Antihistamine only through the medication check.', 'Take a photo and record the trigger in your medical profile.'],
    esc: 'Swelling of the lips, tongue or throat, wheezing, dizziness or vomiting: emergency — press Help ("Severe allergic reaction").', src: ['immune'], emg: 'allergy' },
  { id: 'MED-102', cat: 'medical', title: 'Floaters or flashes in the vision', q: 'floaters flashes of light spots in vision cobwebs dark spots flashing lights moscas volantes manchas en la vista destellos luces corps flottants mouches volantes eclairs',
    a: 'Floaters are small specks or threads that drift across your vision; most are harmless. A sudden shower of new floaters, flashes of light or a dark curtain can mean a torn or detached retina.',
    steps: ['Note when they started and in which eye.', 'Cover one eye at a time and look for a shadow or a missing area.', 'Log it in Vitals as a vision change.'],
    esc: 'Sudden new floaters, flashes, a curtain or shadow over the vision, or vision loss: urgent — tell the Crew Medical Officer now.', src: ['sans'] },
  { id: 'MED-103', cat: 'medical', title: 'Kidney pain or kidney infection', q: 'kidney pain kidney infection pain in the back below ribs flank pyelonephritis dolor de rinones infeccion de rinon rinones pielonefritis dor nos rins infeccao renal douleur aux reins',
    a: 'Kidney pain is felt in the back, below the ribs, on one or both sides. With fever, chills and burning urine it suggests a kidney infection; pain in waves towards the groin suggests a stone.',
    steps: ['Measure temperature, heart rate and blood pressure.', 'Do a urine dipstick test and log it (Vitals → Urine test).', 'Drink water regularly unless told otherwise.'],
    esc: 'Fever, chills, vomiting or blood in the urine with back pain: tell the Crew Medical Officer now — it needs antibiotics. Severe pain in waves: see "Kidney stone warning signs".', src: ['renal', 'micro'] },
  { id: 'MED-104', cat: 'medical', title: 'Urinating at night or prostate symptoms', q: 'peeing at night waking up to pee frequent urination prostate nocturia orinar de noche me levanto a orinar prostata xixi a noite pipi la nuit',
    a: 'Waking up to urinate can come from drinking late, caffeine, a urinary infection, high blood sugar or, in men, an enlarged prostate, which also makes the stream weaker.',
    steps: ['Drink most of your fluids before the evening; no caffeine after midday.', 'Urinate just before your sleep period.', 'Log how many times you wake and how strong the stream is.', 'Do a urine dipstick test if it is new.'],
    esc: 'Burning, blood in the urine, fever, strong thirst, or being unable to urinate: tell the Crew Medical Officer today.', src: ['renal'] },
  { id: 'MED-105', cat: 'medical', title: 'Testicular pain or swelling', q: 'testicle pain testicular pain balls hurt scrotum swelling dolor de testiculos testiculos huevos escroto hinchado testiculo dor nos testiculos douleur testicule',
    a: 'Pain or swelling in a testicle can come from an injury, an infection or a twisted testicle (torsion). Sudden severe pain is an emergency, because torsion must be treated within hours.',
    steps: ['Check for a lump, swelling or redness, and compare both sides.', 'Support the scrotum with snug underwear; cold pack (wrapped) for swelling.', 'Measure your temperature.'],
    esc: 'Sudden severe pain, pain with vomiting, or a testicle sitting higher than usual: emergency — tell the Crew Medical Officer now. A painless lump: tell the CMO at the next conference.', src: ['med'] },
  { id: 'MED-106', cat: 'medical', title: 'Irregular or missed period', q: 'irregular period missed period late period no period spotting cycle regla irregular no me baja retraso menstrual periodo irregular manchado menstruacao atrasada regles irregulieres retard de regles',
    a: 'Stress, weight change, hard exercise, disrupted sleep and the hormone treatment some crew use in flight can all change the cycle. If pregnancy is possible, it should be ruled out.',
    steps: ['Log the dates of bleeding and spotting.', 'Do a pregnancy test from the medical kit if pregnancy is possible.', 'Note any change in medicines or hormone treatment.'],
    esc: 'Very heavy bleeding, bleeding with severe pain or dizziness, or a positive pregnancy test: tell the Crew Medical Officer now.', src: ['med'] },
  { id: 'MED-107', cat: 'medical', title: 'Vaginal discharge or yeast infection', q: 'vaginal discharge yeast infection thrush itching vagina candida discharge smell flujo vaginal hongos vaginales candidiasis picazon vaginal corrimento candidiase pertes blanches mycose vaginale',
    a: 'A change in vaginal discharge with itching or burning is often a yeast infection (thick white discharge) or a bacterial imbalance (thin discharge with a fishy smell). Warm, damp clothing, antibiotics and limited washing make them more likely.',
    steps: ['Wear breathable underwear, change it daily and keep the area dry.', 'Wash with water only; avoid scented products.', 'Treatment only through the medication check.', 'Note the symptoms, colour and smell to describe them to the CMO.'],
    esc: 'Fever, pelvic pain, sores or blisters, unusual bleeding, or no improvement after treatment: tell the Crew Medical Officer.', src: ['micro'] },
  { id: 'MED-108', cat: 'medical', title: 'Breast lump or breast pain', q: 'breast lump lump in breast breast pain nipple discharge breast change bulto en la mama bolita en el seno dolor en los senos nodulo no seio caroco na mama boule dans le sein',
    a: 'Most breast lumps are not cancer, but every new lump must be checked. Breast pain alone is usually hormonal. Breast changes can happen in men and women.',
    steps: ['Note the size, where it is, and whether it moves or is tender.', 'Check again after your next period, if you have one.', 'Look for skin dimpling, nipple changes or discharge.', 'Tell the Crew Medical Officer at the next conference — an ultrasound exam may be possible.'],
    esc: 'A hard, fixed lump, skin dimpling, bloody nipple discharge or a lump in the armpit: tell the Crew Medical Officer this week.', src: ['med', 'rad'] },
  { id: 'MED-109', cat: 'medical', title: 'Thyroid symptoms', q: 'thyroid overactive thyroid underactive thyroid hyperthyroid hypothyroid goiter always cold weight change tiroides hipertiroidismo hipotiroidismo bocio tireoide thyroide',
    a: 'The thyroid sets the body\'s pace. Overactive: fast heartbeat, tremor, sweating, weight loss, anxiety. Underactive: tiredness, feeling cold, weight gain, constipation, dry skin. A swelling at the front of the neck can also be the thyroid.',
    steps: ['Log heart rate, weight, energy and temperature for a week.', 'Note any swelling at the front of the neck.', 'Ask for a thyroid blood test at the next medical conference.', 'Keep taking any thyroid medicine as prescribed; changes only through the Crew Medical Officer.'],
    esc: 'A very fast or irregular heartbeat, fever with confusion, or trouble swallowing or breathing: tell the Crew Medical Officer now.', src: ['med'] },
  { id: 'MED-110', cat: 'medical', title: 'Flu or COVID-like illness', q: 'flu influenza covid coronavirus body aches fever and cough loss of smell viral illness gripe covid coronavirus dolor de cuerpo cuerpo cortado perdi el olfato grippe',
    a: 'Flu and COVID-like illnesses cause fever, cough, sore throat, body aches, tiredness and sometimes loss of smell or taste. In a closed cabin they can spread to the whole crew, so isolate early.',
    steps: ['Wear a mask and, if possible, sleep and eat apart from the crew.', 'Log temperature, heart rate and SpO₂ twice a day.', 'Rest and drink fluids.', 'Use a test from the medical kit if available; fever medicine only through the medication check.'],
    esc: 'SpO₂ under 94%, breathlessness, chest pain, confusion or fever over 39 °C: tell the Crew Medical Officer now. SpO₂ under 90%: press Help.', src: ['immune', 'micro'], emg: 'breathing' },
  { id: 'MED-111', cat: 'medical', title: 'Shingles', q: 'shingles herpes zoster painful rash on one side band of blisters burning skin culebrilla herpes zoster ampollas dolorosas cobreiro zona',
    a: 'Shingles is the chickenpox virus waking up again. It starts with burning or tingling on one side of the body, and a few days later a band of painful blisters appears. Stress and the immune changes of spaceflight can reactivate it.',
    steps: ['Keep the rash clean, dry and covered.', 'Do not touch the blisters and wash hands — the fluid can give chickenpox to someone who never had it.', 'Tell the Crew Medical Officer early: antiviral treatment works best in the first 3 days.', 'Pain relief only through the medication check.'],
    esc: 'A rash near the eye or on the tip of the nose, a rash spreading over the body, or fever with confusion or weakness: tell the Crew Medical Officer now.', src: ['immune'] },
  { id: 'MED-112', cat: 'medical', title: 'Snoring or sleep apnoea', q: 'snoring snore sleep apnea stop breathing at night gasping ronco roncar ronquidos ronco mucho apnea del sueno ronco ronqueira apneia ronfle ronflement',
    a: 'Snoring is common and often harmless. Pauses in breathing, gasping or choking during sleep, with heavy daytime sleepiness, can be sleep apnoea, which affects alertness and the heart. Congestion and tiredness make snoring worse.',
    steps: ['Ask a crewmate, or use the sleep recording, to note pauses in breathing.', 'Treat a blocked nose with saline spray.', 'Avoid late heavy meals; sleep medicine only through the medication check.', 'Log daytime sleepiness and morning headaches.'],
    esc: 'Pauses in breathing, waking up gasping, or falling asleep during tasks: tell the Crew Medical Officer.', src: ['sleep'] },
  { id: 'MED-113', cat: 'medical', title: 'Bad breath', q: 'bad breath halitosis breath smells mouth odor mal aliento aliento feo me huele la boca mau halito bafo mauvaise haleine',
    a: 'Bad breath usually comes from the mouth: food stuck between the teeth, gum problems, a dry mouth or a coated tongue. In flight, less water and fewer hygiene options make it more common.',
    steps: ['Brush twice a day, floss daily and clean your tongue.', 'Drink water often to keep the mouth moist.', 'Rinse your mouth after meals.'],
    esc: 'Bleeding or swollen gums, a painful tooth, or bad breath with fever or a sore throat: tell the Crew Medical Officer.', src: ['med'] },
  { id: 'MED-114', cat: 'medical', title: 'Excessive sweating or night sweats', q: 'excessive sweating sweat too much night sweats sweaty hands hyperhidrosis sudo demasiado sudoracion excesiva sudores nocturnos manos sudadas suor excessivo suores noturnos transpiration excessive sueurs nocturnes',
    a: 'In microgravity sweat does not drip — it stays on the skin and dries slowly, so you feel sweatier during exercise. Sweating can also come from heat, stress, fever, low blood sugar or an overactive thyroid.',
    steps: ['Towel off during exercise and increase the airflow.', 'Wear breathable clothing and change it after workouts.', 'Drink more and add electrolytes on heavy sweating days.', 'Log night sweats and your temperature.'],
    esc: 'Night sweats with fever or weight loss, or sweating with chest pain, shakiness or confusion: tell the Crew Medical Officer now.', src: ['std2', 'fit'] },
  { id: 'MED-115', cat: 'medical', title: 'Body odour', q: 'body odor body odour smell bad sweat smell armpits smelly feet olor corporal olor a sudor axilas sobacos pies apestosos cheiro corporal odeur corporelle',
    a: 'Without showers and with little laundry, sweat and bacteria build up on skin and clothes. Body odour is normal in flight, but it matters in a small shared space.',
    steps: ['Wash daily with no-rinse soap and wipes, especially armpits, groin and feet.', 'Change underwear and socks daily and exercise clothes as planned.', 'Air out shoes and clothes; store used clothing sealed.'],
    esc: 'A new strong smell from the breath, urine or a wound, or with fever or redness: tell the Crew Medical Officer.', src: ['std2', 'micro'] },
  { id: 'MED-116', cat: 'medical', title: 'Hair loss', q: 'hair loss losing hair hair falling out bald patches thinning hair caida del pelo se me cae el pelo calvicie perdida de cabello alopecia queda de cabelo chute de cheveux',
    a: 'Losing some hair every day is normal. Stress, illness, low iron or protein, thyroid problems and some medicines can increase shedding, usually 2–3 months after the trigger. Mission radiation doses are far below those that cause hair loss.',
    steps: ['Comb over a vacuum or a wipe so loose hair does not float into equipment or eyes.', 'Eat the full menu, including protein and iron.', 'Note when it started and any illness, stress or new medicine before it.'],
    esc: 'Round bald patches, hair loss with a rash or scalp pain, or hair loss after a radiation event: tell the Crew Medical Officer.', src: ['food', 'rad'] },
  { id: 'MED-117', cat: 'medical', title: 'Cold hands and feet', q: 'cold hands cold feet always cold white fingers poor circulation raynaud pies frios manos frias frio en los pies dedos blancos mala circulacion pes frios maos frias pieds froids mains froides',
    a: 'Cold hands and feet are common in a cool cabin, during long still work and with stress. Fingers that turn white or blue in the cold and then red (Raynaud\'s) are usually harmless but uncomfortable.',
    steps: ['Wear socks, gloves and an extra layer; ask for a warmer module set point.', 'Move your fingers and toes and exercise regularly.', 'Avoid nicotine and too much caffeine.'],
    esc: 'One cold, pale, painful limb, sores on the fingers, or cold with numbness and weakness: tell the Crew Medical Officer now.', src: ['cv', 'std2'] },
  { id: 'MED-118', cat: 'medical', title: 'Vitamin deficiency', q: 'vitamin deficiency vitamins vitamin d low b12 iron deficiency supplements falta de vitaminas vitaminas deficiencia suplementos carencia de vitaminas carence vitamines',
    a: 'Without sunlight the body makes little vitamin D, and long missions limit fresh food. Signs of low vitamins can be vague: tiredness, mouth sores, bleeding gums, tingling or muscle aches. The flight diet and prescribed supplements are designed to cover these needs.',
    steps: ['Take the supplements prescribed for the mission (such as vitamin D), only through the medication check.', 'Eat the full menu, including fruit and vegetables when available.', 'Ask for a blood test at the next medical conference.'],
    esc: 'Bleeding gums with bruising, numbness or tingling in the hands and feet, or severe tiredness: tell the Crew Medical Officer.', src: ['food', 'bone'] },
  { id: 'MED-119', cat: 'medical', title: 'Swollen feet and ankles (both sides)', q: 'swollen ankles swollen feet both legs swollen fluid retention edema puffy legs tobillos hinchados pies hinchados piernas hinchadas retencion de liquidos inchaco chevilles gonflees',
    a: 'Swelling of both feet and ankles is common after landing, in the heat and after long sitting or standing, as fluid moves back into the legs. Swelling of one leg only is different — it can be a clot.',
    steps: ['Raise your legs above heart level for 20 minutes a few times a day.', 'Move: flex your ankles and walk often.', 'Go easy on salt and drink normally.', 'Press the skin for 5 seconds, see if a dent remains, and log it.'],
    esc: 'One-sided swelling, calf pain, breathlessness, chest pain or fast weight gain: tell the Crew Medical Officer now (see "Swollen arm, leg or neck").', src: ['cv'] },
  { id: 'MED-120', cat: 'medical', title: 'Eyelid twitching', q: 'eye twitch eyelid twitching twitchy eye muscle twitch tic me tiembla el ojo parpado tic en el ojo palpebra tremendo paupiere qui saute',
    a: 'A twitching eyelid is very common and harmless. It is usually caused by tiredness, stress, caffeine or eye strain, and stops within days or weeks.',
    steps: ['Get enough sleep and cut back on caffeine.', 'Take breaks from screens and use lubricating eye drops for dry eyes.', 'Put a warm compress on the eyelid for a few minutes.'],
    esc: 'Twitching that closes the eye fully, spreads to other parts of the face, lasts more than 2 weeks, or comes with a drooping eyelid or face: tell the Crew Medical Officer.', src: ['sleep', 'sans'] },
  { id: 'MED-121', cat: 'medical', title: 'Restless legs', q: 'restless legs urge to move legs at night crawling feeling jumpy legs piernas inquietas no puedo dejar de mover las piernas pernas inquietas jambes sans repos',
    a: 'Restless legs cause an uncomfortable urge to move the legs, mainly in the evening or at rest, which eases when you move. Low iron, caffeine, short sleep and some medicines make it worse.',
    steps: ['Stretch and massage the legs before sleep.', 'Cut down on caffeine, especially later in the day.', 'Keep a regular sleep window.', 'Ask for an iron test at the next medical conference.'],
    esc: 'If it keeps you awake most nights: tell the Crew Medical Officer; medicine only through the medication check.', src: ['sleep'] },
  { id: 'MED-122', cat: 'medical', title: 'Dry, cracked lips or hands', q: 'chapped lips cracked lips dry lips cracked hands dry hands split fingertips labios partidos labios resecos manos resecas grietas labios rachados levres gercees mains seches',
    a: 'Dry cabin air and frequent hand cleaning dry out the lips and hands, causing cracks that can sting and bleed.',
    steps: ['Use lip balm and hand cream several times a day.', 'Drink enough water.', 'Do not lick or peel your lips; wear gloves for dirty tasks.'],
    esc: 'Cracks that become red, swollen or full of pus, or sores at the corners of the mouth that do not heal in 2 weeks: tell the Crew Medical Officer.', src: ['std2'] },
  { id: 'MED-123', cat: 'medical', title: 'Nail problems (brittle or fungal nails)', q: 'brittle nails nail fungus thick yellow nails nail changes split nails unas debiles hongos en las unas unas amarillas unas quebradizas unhas fracas micose ongles cassants',
    a: 'Nails can become brittle from dryness and frequent cleaning. Thick, yellow or crumbling nails usually mean a slow fungal infection.',
    steps: ['Keep nails short and dry, and moisturise them.', 'Use your own clippers and file, and collect clippings so they do not float.', 'Antifungal treatment only through the medication check.'],
    esc: 'A new or widening dark streak in a nail, pain with redness and pus around the nail, or a nail lifting after EVA: tell the Crew Medical Officer.', src: ['micro'] },
  { id: 'MED-124', cat: 'medical', title: 'Swollen glands (lymph nodes)', q: 'swollen glands swollen lymph nodes lump in neck lump in armpit ganglios inflamados bolitas en el cuello ganglio inflamado linfonodos inchados ingua ganglions gonfles',
    a: 'Lymph nodes swell when the body fights an infection, for example a sore throat or a cut. They are usually tender and shrink within 2–3 weeks.',
    steps: ['Look for a nearby cause: throat, teeth, skin or scalp.', 'Measure your temperature.', 'Note the size (a pea, a grape) and check again in a week.'],
    esc: 'A node larger than 2 cm, hard, fixed, or painless and growing, lasting more than 3 weeks, or with night sweats, fever or weight loss: tell the Crew Medical Officer.', src: ['immune'] },
  { id: 'MED-125', cat: 'medical', title: 'Splinter or something stuck in the skin', q: 'splinter something stuck in skin metal sliver fiberglass glass shard astilla clavada metal en la piel vidrio clavado farpa lasca echarde',
    a: 'Small slivers of metal, glass or fibreglass from equipment and repairs can get under the skin. Small ones can be removed; deep ones can carry infection.',
    steps: ['Clean the area and your hands, and wear gloves.', 'Pull it out with sterile tweezers at the angle it went in; use tape for tiny fibres.', 'Catch it so it does not float away; clean and cover the wound.', 'Check the area daily for redness.'],
    esc: 'A deep or large object, anything in the eye, near a joint or still bleeding — do not pull it out: keep it still and tell the Crew Medical Officer now.', src: ['med'] },
  { id: 'MED-126', cat: 'medical', title: 'New lump under the skin', q: 'lump under the skin bump cyst lipoma nodule hard lump soft lump bulto bolita debajo de la piel quiste bulto nuevo caroco nodulo cisto bosse kyste',
    a: 'Most small lumps under the skin are harmless (a cyst, a fatty lump or a swollen gland). Lumps that grow, are hard, do not move or are painful need checking.',
    steps: ['Measure it and take a photo with a ruler.', 'Note whether it moves under the skin and whether it is tender or red.', 'Check it again in 2 weeks and compare.'],
    esc: 'Fast growth, hard and fixed, red and hot with fever, or a lump in the breast, testicle, neck or armpit: tell the Crew Medical Officer.', src: ['med', 'rad'] },
  { id: 'MED-127', cat: 'medical', title: 'A mole or skin spot that changed', q: 'mole changed new mole skin spot skin cancer melanoma dark spot lunar lunar que cambio mancha en la piel cancer de piel sinal na pele grain de beaute',
    a: 'Radiation in space adds to the lifetime risk of skin cancer. Check moles with ABCDE: Asymmetry, irregular Border, several Colours, Diameter over 6 mm, and Evolving (changing).',
    steps: ['Photograph the spot with a ruler next to it.', 'Compare it with your pre-flight skin photos if you have them.', 'Check it again in 2–4 weeks.'],
    esc: 'A mole that changes, bleeds, itches or shows any ABCDE sign: tell the Crew Medical Officer so the photos can be shared with ground.', src: ['rad'] },
  { id: 'MED-128', cat: 'medical', title: 'Leaking urine', q: 'leaking urine incontinence bladder leaks when coughing cant hold pee urgency se me escapa la orina incontinencia urinaria perdida de orina escape de urina fuites urinaires',
    a: 'Leaking urine when coughing, laughing or lifting, or a sudden urge you cannot hold, is common and treatable. A urinary infection, constipation, caffeine or weak pelvic floor muscles can cause it.',
    steps: ['Do a urine dipstick test to rule out infection.', 'Pelvic floor exercises: squeeze for 5 seconds, relax for 5, 10 times, 3 times a day.', 'Urinate on a schedule and cut back on caffeine.'],
    esc: 'Leaking with back pain, leg numbness or weakness, or fever, or being unable to empty the bladder: tell the Crew Medical Officer now.', src: ['renal'] },

  { id: 'WB-35', cat: 'wellbeing', title: 'Obsessions and compulsions (OCD)', q: 'ocd obsessive compulsive compulsions checking again and again counting rituals fear of germs washing hands too much toc obsesivo compulsivo compulsiones revisar una y otra vez manias rituales trouble obsessionnel',
    a: 'Obsessive-compulsive patterns are unwanted, repeated thoughts (for example about germs or mistakes) and actions you feel you must do to calm them (checking, washing, counting). Stress and confinement can make them stronger. They are treatable.',
    steps: ['Notice the urge and delay the ritual a little longer each time.', 'Agree with a crewmate on one check for safety-critical steps, then stop checking.', 'Use slow breathing to ride out the anxiety — it falls on its own.', 'Request a private psychological conference — therapy works well for this.'],
    esc: 'If rituals take more than an hour a day, stop you working, or the thoughts frighten you: tell the Crew Medical Officer and request a conference.', src: ['bmed'] },
  { id: 'WB-36', cat: 'wellbeing', title: 'Post-traumatic stress (PTSD)', q: 'ptsd post traumatic stress trauma reliving flashbacks on edge startle hypervigilant estres postraumatico tept revivir sobresalto en alerta stress pos traumatico stress post traumatique',
    a: 'After a frightening event — in flight or in the past — some people keep reliving it, avoid reminders, feel constantly on edge and sleep badly for more than a month. This is post-traumatic stress, and it is treatable.',
    steps: ['When a memory hits, ground yourself: feet against a restraint, name what you see.', 'Keep sleep, exercise and contact with the crew regular.', 'Do not use alcohol or sleep medicines to block memories without the Crew Medical Officer.', 'Request a private psychological conference.'],
    esc: 'If it stops you working safely, or you think of hurting yourself: tell the Crew Medical Officer today; press Help if you are in danger.', src: ['bmed', 'sleep'] },
  { id: 'WB-37', cat: 'wellbeing', title: 'Social anxiety and shyness', q: 'social anxiety shy shyness fear of speaking embarrassed being judged nervous with people fobia social ansiedad social timidez miedo a hablar en publico miedo al ridiculo ansiedade social anxiete sociale timidite',
    a: 'Social anxiety is a strong fear of being judged or embarrassed, for example when speaking at a crew meeting or on a call with ground. In a small crew you cannot avoid people, which can feel harder at first.',
    steps: ['Prepare 2–3 points before meetings or calls.', 'Notice the thought "they think I am…" and ask what the evidence is.', 'Take small steps: one comment in each meeting.', 'Request a private psychological conference if it holds you back.'],
    esc: 'If it causes panic or isolation, or you avoid tasks because of it: request a psychological conference.', src: ['bmed', 'team'] },
  { id: 'WB-38', cat: 'wellbeing', title: 'Phobias (needles, blood, the dark)', q: 'phobia phobias irrational fear fear of needles fear of blood fear of the dark fobia fobias miedo irracional miedo a las agujas miedo a la sangre miedo a la oscuridad phobie',
    a: 'A phobia is an intense fear of one specific thing — needles, blood, the dark, open space. The fear is out of proportion, but it is real. Phobias respond well to gradual exposure with support.',
    steps: ['Tell the Crew Medical Officer if the fear affects medical care (for example needles or blood draws).', 'Slow breathing: in for 4, out for 6.', 'Face it in small steps, with a crewmate, and stay until the fear falls.', 'Request a psychological conference for an exposure plan.'],
    esc: 'If you faint at the sight of blood or needles, lie down first. If the fear stops you doing safety tasks: tell the commander.', src: ['bmed'] },
  { id: 'WB-39', cat: 'wellbeing', title: 'Attention trouble and distraction (ADHD-like)', q: 'adhd attention deficit cant focus easily distracted restless hyperactive procrastinate tdah deficit de atencion me distraigo hiperactivo no me puedo enfocar procrastinar deficit de atencao',
    a: 'Getting distracted, losing track of tasks and feeling restless are common with poor sleep, stress and a busy timeline. Some people have lifelong attention differences (ADHD) that mission routines make more noticeable.',
    steps: ['Break tasks into small steps and tick each one off.', 'Use timers: 25 minutes of focus, 5 minutes of break.', 'Remove distractions: notifications off, one window at a time.', 'Ask a crewmate to cross-check critical steps.'],
    esc: 'If it leads to errors in safety-critical work: tell the commander. Any medicine for attention only through the Crew Medical Officer.', src: ['bmed', 'sleep'] },
  { id: 'WB-40', cat: 'wellbeing', title: 'Unusual highs: very high energy, little sleep', q: 'manic mania hypomania very high energy no need for sleep racing thoughts euphoric reckless bipolar euforia mania mucha energia no necesito dormir pensamientos acelerados euforico euphorie bipolaire',
    a: 'Several days of unusually high energy, little need for sleep, racing thoughts, fast talking, big plans or risky decisions can be a "high" (hypomania or mania). Sleep loss can trigger it. It is a medical matter, not a change of character.',
    steps: ['Protect your sleep window, even when you feel you do not need it.', 'Avoid caffeine and big decisions for now.', 'Ask a trusted crewmate to tell you if you seem different.', 'Tell the Crew Medical Officer.'],
    esc: 'Three or more nights of little sleep with high energy, risky behaviour, or beliefs others do not share: tell the Crew Medical Officer today.', src: ['bmed', 'sleep'] },
  { id: 'WB-41', cat: 'wellbeing', title: 'Eating disorder', q: 'eating disorder anorexia bulimia making myself vomit purging restricting food afraid of gaining weight body image trastorno alimenticio anorexia bulimia miedo a engordar imagen corporal transtorno alimentar trouble alimentaire',
    a: 'Restricting food, bingeing, making yourself vomit, or a strong fear of gaining weight are signs of an eating disorder. In space, eating too little quickly costs muscle and bone, so it is a health risk, not a private failing.',
    steps: ['Tell the Crew Medical Officer or someone you trust — it is confidential.', 'Eat at fixed times with the crew.', 'Request a private psychological conference.'],
    esc: 'Fainting, a very slow heartbeat, vomiting blood or fast weight loss: tell the Crew Medical Officer now.', src: ['food', 'bmed'] },
  { id: 'WB-42', cat: 'wellbeing', title: 'Addiction or dependence', q: 'addiction dependence hooked cant stop gambling pills alcohol dependence compulsive use adiccion dependencia enganchado no puedo dejar vicio adicao dependance',
    a: 'Dependence means needing a substance or a behaviour (alcohol, sleeping pills, pain medicine, gaming, gambling) to feel normal, and struggling to stop. On a mission supplies are limited and withdrawal can affect safety, so it helps to plan ahead.',
    steps: ['Be honest with the Crew Medical Officer — it is confidential and it is about safety, not blame.', 'Do not take extra doses of any medicine; every dose through the medication check.', 'Replace the habit with exercise, a call or a task.', 'Request a private psychological conference.'],
    esc: 'Shaking, sweating, confusion, a seizure or seeing things after stopping a substance: tell the Crew Medical Officer now.', src: ['bmed', 'pharm'] },
  { id: 'WB-43', cat: 'wellbeing', title: 'Jealousy', q: 'jealous jealousy envy envious partner cheating crewmate favoured celos celoso envidia mi pareja me engana ciumes ciume inveja jalousie jaloux',
    a: 'Jealousy grows easily when you are far from a partner and cannot see what is happening, or when you feel others on the crew are favoured. The feeling is normal; acting on it in anger is what causes harm.',
    steps: ['Name the feeling and notice the story your mind is telling.', 'Wait before you send a message or confront anyone.', 'Talk about it calmly, in private, at a planned time.', 'Share it with the flight psychologist if it keeps coming back.'],
    esc: 'If jealousy leads to threats, controlling behaviour or thoughts of hurting someone: tell the Crew Medical Officer or the commander now.', src: ['bmed', 'team'] },
  { id: 'WB-44', cat: 'wellbeing', title: 'Anniversary of a loss', q: 'anniversary of a death grief anniversary birthday of someone who died missing someone who passed away aniversario de muerte aniversario luctuoso cumpleanos de alguien que murio fallecio aniversario de morte anniversaire de deces',
    a: 'Anniversaries, birthdays and holidays can bring grief back strongly, even years later — and being far from family on that day can make it harder.',
    steps: ['Mark the day: plan a small ritual, a photo, a letter or a moment at the window.', 'Tell the crew so they understand and can support you.', 'Schedule a call with family around that date.', 'Lighten your workload that day if possible.'],
    esc: 'If grief stops you sleeping or working for days, or you feel hopeless: request a private psychological conference.', src: ['bmed'] },
  { id: 'WB-45', cat: 'wellbeing', title: 'Sexual health worries', q: 'sexual health libido low sex drive erection problems erectile dysfunction pain during sex salud sexual deseo sexual bajo disfuncion erectil problemas de ereccion saude sexual disfuncao eretil sante sexuelle',
    a: 'Changes in sexual desire or function are common on long missions: stress, tiredness, hormones, medicines and distance from a partner all play a part. These are medical questions and they are confidential.',
    steps: ['Note any new medicine — some lower desire or function.', 'Look after sleep, exercise and stress, which all affect sexual health.', 'Talk privately with the Crew Medical Officer or the flight surgeon.'],
    esc: 'A painful erection lasting more than 4 hours, testicular pain, genital sores or discharge: tell the Crew Medical Officer now.', src: ['bmed', 'med'] },
  { id: 'WB-46', cat: 'wellbeing', title: 'Lying awake with worries', q: 'awake with worries worrying in bed racing mind at night mind wont switch off thinking in bed preocupaciones en la cama mente acelerada de noche pensando en la cama pensamentos a noite pensees la nuit',
    a: 'When the mind keeps running at bedtime, sleep will not come. Worry is easier to quiet when it has somewhere to go.',
    steps: ['Two hours before sleep, write down your worries and one next step for each.', 'In bed, breathe slowly (in for 4, out for 6) and relax each muscle group.', 'If you are still awake after 20 minutes, get up, do something calm in dim light, then try again.', 'Keep the same wake time every day.'],
    esc: 'Fewer than 6 hours for 3+ nights: tell the Crew Medical Officer; sleep medicine only through the CMO.', src: ['sleep', 'bmed'] },
  { id: 'WB-47', cat: 'wellbeing', title: 'Feeling numb or without emotions', q: 'feel numb no emotions empty feel nothing flat disconnected dont feel anything no siento nada insensible apagado entumecido emocionalmente nao sinto nada ressens rien',
    a: 'Feeling numb or empty — no joy, no sadness — can follow long stress, exhaustion, a shock or low mood. It is the mind protecting itself, and it usually lifts with rest and support.',
    steps: ['Check the basics: sleep, food and exercise.', 'Do one small thing you used to enjoy, even without feeling like it.', 'Tell a crewmate or the flight psychologist how it feels.'],
    esc: 'If it lasts more than 2 weeks, or comes with hopelessness or thoughts of hurting yourself: tell the Crew Medical Officer; press Help if you are in danger.', src: ['bmed'] },
  { id: 'WB-48', cat: 'wellbeing', title: 'Decision fatigue', q: 'decision fatigue too many decisions cant decide indecisive mentally drained choices fatiga de decisiones no puedo decidir indeciso demasiadas decisiones cansancio mental fadiga de decisao fatigue decisionnelle',
    a: 'Making many decisions in a day wears down judgement. Late in the day people take the easy option or avoid deciding. On a mission with less ground support, this matters.',
    steps: ['Make important decisions early in your day.', 'Use checklists and standard procedures for routine choices.', 'Share decisions with a crewmate and sleep on the ones that are not urgent.', 'Take short breaks between decision-heavy tasks.'],
    esc: 'If tiredness affects safety-critical decisions: tell the commander so work can be shared.', src: ['ei', 'sleep'] },
  { id: 'WB-49', cat: 'wellbeing', title: 'Panic at night', q: 'panic at night waking up panicking night panic attack wake up with heart racing fear at night panico nocturno me despierto con panico me despierto asustado panico noturno panique nocturne',
    a: 'Some people wake from sleep with a racing heart, breathlessness and fear. Night panic is frightening but not dangerous, and it often follows stress, caffeine or sleep loss.',
    steps: ['Sit up, turn on a light and hold a handhold or restraint.', 'Breathe in for 4 and out for 6 until your heart slows.', 'Check your heart rate and SpO₂ to reassure yourself.', 'Log it with your caffeine and stress of that day.'],
    esc: 'Chest pain, SpO₂ under 94%, or panic that does not settle in 20 minutes: press Help. If it happens often: request a psychological conference.', src: ['bmed', 'sleep'] },
  { id: 'WB-50', cat: 'wellbeing', title: 'Urges to harm yourself', q: 'self harm cutting myself urge to hurt myself burning myself hitting myself autolesion cortarme lastimarme hacerme cortes ganas de hacerme dano automutilacao automutilation',
    a: 'Urges to hurt yourself usually come when emotions feel unbearable. You deserve help, and the urge does pass. Telling someone now is the most important step.',
    steps: ['Tell a crewmate or the Crew Medical Officer now; do not stay alone.', 'Put tools, sharp objects and medicines out of reach.', 'Hold ice or a cold pack, or do hard exercise, until the urge drops.', 'Request a private conference with the flight psychologist today.'],
    esc: 'This is urgent: press Help now. If you have already hurt yourself, press Help so the wound can be treated.', src: ['bmed'], emg: 'psych' },
  { id: 'WB-51', cat: 'wellbeing', title: 'Helping a crewmate who is struggling', q: 'help a crewmate struggling colleague not ok worried about a crewmate how to help someone crewmate depressed ayudar a un companero companero mal companero triste mi companero esta mal ajudar um colega aider un collegue',
    a: 'Signs that a crewmate is struggling: withdrawing, irritability, poor sleep, eating changes, mistakes, or talk of hopelessness. Asking does not make things worse — it helps.',
    steps: ['Find a private moment and ask directly: "How are you really doing?"', 'Listen without fixing or judging, and thank them for telling you.', 'Offer practical help with tasks and encourage a psychological conference.', 'Look after yourself too, and keep their confidence unless they are in danger.'],
    esc: 'If they talk about hurting themselves or others, or are not safe: stay with them and press Help.', src: ['team', 'bmed'], emg: 'psych' },
  { id: 'WB-52', cat: 'wellbeing', title: 'Work–life balance', q: 'work life balance always working no free time no time for myself personal time equilibrio trabajo vida no tengo tiempo libre trabajo todo el dia tiempo para mi tempo livre equilibre vie travail',
    a: 'On a mission, work and home are the same place, so work easily fills every hour. Protected personal time keeps performance and mood up over months.',
    steps: ['Keep your off-duty time and weekends as real time off.', 'Have a "shutdown" routine at the end of the work day.', 'Plan personal activities: hobbies, calls, reading, time at the window.', 'Tell the commander if the timeline keeps eating your rest.'],
    esc: 'If you are exhausted or making mistakes: see "Burnout" and tell the commander.', src: ['sleep', 'team'] },
  { id: 'WB-53', cat: 'wellbeing', title: 'Sleeping too much', q: 'sleeping too much oversleeping always sleepy hard to wake up hypersomnia drowsy all day duermo mucho duermo demasiado siempre tengo sueno somnolencia durmo demais sonolencia je dors trop somnolence',
    a: 'Needing much more sleep than usual, or being sleepy all day, can come from poor-quality sleep, a shifted body clock, low mood, illness or some medicines.',
    steps: ['Keep a fixed wake time and get bright light right after waking.', 'Log the hours slept, naps and how rested you feel.', 'Exercise in the first part of your day.', 'Check for low mood, snoring or a new medicine.'],
    esc: 'Falling asleep during tasks, or sleepiness with low mood or loss of interest: tell the Crew Medical Officer.', src: ['sleep', 'bmed'] },
  { id: 'WB-54', cat: 'wellbeing', title: 'Crying spells', q: 'crying spells cant stop crying cry for no reason tearful crying a lot lloro sin razon no puedo dejar de llorar ganas de llorar lloro mucho choro sem motivo chorar pleurer sans raison',
    a: 'Crying often, or for no clear reason, can be a release after stress, tiredness or sad news. It can also be a sign of low mood if it happens most days.',
    steps: ['Let it happen in a private space; crying is not weakness.', 'Notice what came before: tiredness, a call, a memory.', 'Talk to someone you trust about it.', 'Log your mood for a week.'],
    esc: 'Crying most days for 2 weeks, or with hopelessness or thoughts of hurting yourself: tell the Crew Medical Officer and request a conference.', src: ['bmed'] },
  { id: 'WB-55', cat: 'wellbeing', title: 'Fear of launch, landing or flying', q: 'fear of flying fear of launch fear of landing scared of reentry afraid of the rocket docking miedo a volar miedo al despegue miedo al aterrizaje reentrada medo de voar pouso peur de voler atterrissage decollage',
    a: 'Launch, docking, re-entry and landing are the most dynamic moments of a mission, and fear before them is common, even in experienced crews.',
    steps: ['Go through the procedure and your role step by step — knowing the plan reduces fear.', 'Practise slow breathing for the high-g phases.', 'Talk with crewmates who have flown before.', 'Request a psychological conference before the event.'],
    esc: 'If fear stops you sleeping or doing your tasks: tell the commander and request a conference.', src: ['bmed', 'sensori'] },
  { id: 'WB-56', cat: 'wellbeing', title: 'Shifted sleep schedule (body clock)', q: 'shift schedule change body clock jet lag night shift circadian desfase horario cambio de turno reloj biologico turno de noche fuso horario decalage horaire',
    a: 'Docking, EVAs and other events often shift the sleep schedule. Shifts of more than an hour a day disturb sleep, mood and alertness.',
    steps: ['Shift your sleep by no more than 1 hour a day when you can plan ahead.', 'Use bright light when you need to be awake and darkness before sleep.', 'No caffeine in the 6 hours before your new sleep time.', 'Pair up for critical tasks during the shift.'],
    esc: 'Severe sleepiness during critical tasks: tell the commander; sleep medicine only through the Crew Medical Officer.', src: ['sleep'] },
  { id: 'WB-57', cat: 'wellbeing', title: 'No privacy or personal space', q: 'no privacy personal space never alone need time alone crowded falta de privacidad espacio personal necesito estar solo privacidade intimite',
    a: 'Living and working together 24 hours a day without real privacy is one of the hardest parts of a long mission. Needing time alone is healthy, not antisocial.',
    steps: ['Plan daily time alone in your sleep station and let the crew know.', 'Agree on a crew signal for "do not disturb".', 'Use headphones, a book or a window as personal space.'],
    esc: 'If the lack of space leads to constant irritation or conflict: talk to the commander or request a conference.', src: ['team', 'std2'] },
  { id: 'WB-58', cat: 'wellbeing', title: 'Frustration with mission control', q: 'mission control frustration ground control conflict us versus them micromanaged no autonomy communication delay control de mision frustracion con tierra centro de control controle de mission',
    a: 'Crews often feel frustrated with the ground: too many tasks, little say in the schedule, or long communication delays. It is a known pattern on long missions, and naming it helps.',
    steps: ['Write down the specific issue and a proposed change.', 'Raise it through the commander at the planning conference.', 'Use written messages for complex topics when there is a long delay.', 'Assume good intent; the ground often lacks your view from on board.'],
    esc: 'If the conflict affects safety or crew morale: the commander should ask for a private conference with mission management.', src: ['team', 'ei'] },
  { id: 'WB-59', cat: 'wellbeing', title: 'Health anxiety (worrying about being ill)', q: 'health anxiety worried i am ill hypochondria afraid i have a disease checking symptoms cancer worry hipocondria miedo a estar enfermo hipocondriaco medo de doenca hypocondrie',
    a: 'Far from hospitals, it is natural to worry about every symptom. Constant checking and searching makes the worry grow rather than shrink.',
    steps: ['Log the symptom once and follow its protocol; then stop checking for a set time.', 'Ask the Crew Medical Officer once, and trust the plan.', 'Notice the "what if" thought and bring your attention back to the present.', 'Request a psychological conference if worry fills much of your day.'],
    esc: 'New danger signs (chest pain, trouble breathing, fainting, confusion): press Help — the worry rule never applies to these.', src: ['bmed'] },
  { id: 'WB-60', cat: 'wellbeing', title: 'Faith, spirituality and rituals', q: 'faith religion pray prayer spirituality spiritual religious holiday god fe religion rezar oracion espiritualidad dios orar religiao spiritualite prier',
    a: 'Faith and personal rituals are a source of strength for many crew members. Keeping them in space takes planning, but it is possible.',
    steps: ['Plan time for prayer or reflection in your schedule.', 'Bring or request small items or texts that matter to you.', 'Share important religious holidays with the crew and ground.'],
    esc: 'If spiritual distress comes with hopelessness: request a private psychological conference.', src: ['bmed', 'team'] },
  { id: 'WB-61', cat: 'wellbeing', title: 'Embarrassment about the body, hygiene or the toilet', q: 'embarrassed embarrassment body toilet shared hygiene bodily functions ashamed of my body verguenza del cuerpo bano compartido verguenza ir al bano vergonha banheiro gene toilettes',
    a: 'Using a shared toilet, managing hygiene with little water, and body noises or smells in a small space can be embarrassing. Every crew member deals with the same things.',
    steps: ['Agree on crew courtesy rules early (privacy curtains, ventilation, knocking).', 'Keep hygiene supplies stocked in your own kit.', 'Use humour and plain talk — it reduces embarrassment for everyone.'],
    esc: 'If embarrassment stops you drinking, eating or using the toilet normally: tell the Crew Medical Officer.', src: ['team', 'std2'] },

  /* ---------- general fallbacks: used when no specific protocol matches ---------- */
  { id: 'GEN-01', cat: 'medical', fallback: true, title: 'A symptom that is not in the onboard list', q: 'symptom general other symptom sintoma general otro sintoma',
    a: 'There is no specific onboard protocol for this symptom, so use the general approach: check for danger signs, measure, record and tell the Crew Medical Officer.',
    steps: ['Danger signs first: chest pain, trouble breathing, fainting, confusion, one-sided weakness, severe bleeding or the worst pain of your life → press Help now.', 'Measure heart rate, blood pressure, temperature and SpO₂ and log them.', 'Write down: where it is, since when, how strong (0–10), what makes it better or worse, and anything that came with it.', 'Rest, drink water and do not take any medicine without the medication check.', 'Tell the Crew Medical Officer and ask for a medical conference with ground.'],
    esc: 'If it gets worse, lasts more than 24 hours, or you are worried: tell the Crew Medical Officer today.', src: ['med'] },
  { id: 'GEN-02', cat: 'wellbeing', fallback: true, title: 'A feeling or worry that is not in the onboard list', q: 'feeling emotion general sentimiento emocion general',
    a: 'There is no specific onboard protocol for this, but what you feel matters. Many feelings on long missions come from sleep, workload, distance from home and confinement.',
    steps: ['Name what you feel and write it down — it helps to sort it out.', 'Talk to a crewmate you trust today.', 'Check the basics: sleep, meals, exercise and time to yourself.', 'Request a private psychological conference — it is confidential.'],
    esc: 'If you have thoughts of hurting yourself or someone else, press Help now.', src: ['bmed', 'team'] },
  /* ---------- ship problems ---------- */
  { id: 'SHIP-01', cat: 'ship', title: 'High cabin CO₂', q: 'co2 carbon dioxide high co2 scrubber cdra air stuffy dioxido de carbono co2 alto aire pesado depurador',
    a: 'High CO₂ causes headache, poor concentration and poor sleep long before it becomes dangerous.',
    steps: ['Check the CO₂ reading and which removal system is running.', 'Increase airflow: open hatches, turn on fans, avoid dead-air pockets.', 'Swap or regenerate the CO₂ scrubber cartridge (check stock in the ship inventory).', 'Limit exercise in the affected module until it drops.'],
    esc: 'Above the mission limit or rising after the swap: notify ground; if crew have symptoms, move to the cleanest module with masks ready.', src: ['std2'] },
  { id: 'SHIP-02', cat: 'ship', title: 'Fire or smoke', q: 'fire smoke burning smell flames incendio fuego humo olor a quemado llamas',
    a: 'Fire is one of the three main spacecraft emergencies. Act fast and as a crew.',
    steps: ['Sound the alarm and tell the crew.', 'Put on masks or breathing apparatus.', 'Remove power to the affected equipment.', 'Use the fire extinguisher at the port or equipment; close hatches to isolate the module.', 'Account for every crew member.'],
    esc: 'Notify ground immediately; follow the vehicle fire procedure. Treat anyone exposed with the "Smoke or toxic gas" protocol.', src: ['std2'], emg: 'toxic' },
  { id: 'SHIP-03', cat: 'ship', title: 'Rapid depressurisation or air leak', q: 'leak depressurization pressure drop air leak hull breach fuga despresurizacion perdida de presion fuga de aire',
    a: 'A pressure drop is one of the three main spacecraft emergencies.',
    steps: ['Sound the alarm; gather the crew.', 'Check the rate of pressure drop and time to minimum safe pressure.', 'Move to the safe-haven or return vehicle if the rate is high.', 'If time allows, find the leak by closing hatches module by module.', 'Put on masks if pressure keeps falling.'],
    esc: 'Notify ground immediately. Treat symptoms (ear pain, dizziness, breathlessness) after the event.', src: ['std2', 'hypoxia'] },
  { id: 'SHIP-04', cat: 'ship', title: 'Toxic leak (ammonia or chemical)', q: 'ammonia toxic leak chemical spill fumes smell amoniaco fuga toxica derrame quimico vapores olor',
    a: 'A toxic atmosphere is one of the three main spacecraft emergencies.',
    steps: ['Masks or breathing apparatus on first.', 'Leave the contaminated area and close the hatch behind you.', 'Flush eyes and skin with water if exposed.', 'Follow the vehicle toxic-release procedure.'],
    esc: 'Notify ground; anyone exposed follows the "Smoke or toxic gas" protocol.', src: ['std2'], emg: 'toxic' },
  { id: 'SHIP-05', cat: 'ship', title: 'Power loss', q: 'power loss outage blackout electrical failure no power apagon falla electrica sin energia corte de luz',
    a: 'Life support has priority on any remaining power.',
    steps: ['Check the power system status and which loads are off.', 'Shed non-essential loads.', 'Confirm CO₂ removal, ventilation and oxygen are running.', 'Use portable lights.'],
    esc: 'If life support is affected: masks and portable oxygen ready, notify ground.', src: ['ei'] },
  { id: 'SHIP-06', cat: 'ship', title: 'Water recycling or water supply failure', q: 'water recycler failure no water water shortage reciclador de agua sin agua falla agua escasez',
    a: 'Drinking water comes first; hygiene water can be reduced.',
    steps: ['Check stored water volume in the ship inventory.', 'Switch to stored water; ration hygiene use.', 'Troubleshoot the recycler per its procedure (filters, pumps, conductivity).', 'Keep drinking at least 2 L a day.'],
    esc: 'If stored water will not last until repair or resupply: notify ground to re-plan.', src: ['std2', 'renal'] },
  { id: 'SHIP-07', cat: 'ship', title: 'Cabin too hot, too cold or too humid', q: 'temperature too hot too cold humidity condensation calor frio humedad condensacion',
    a: 'Temperature and humidity affect sleep, comfort and electronics.',
    steps: ['Check the thermal control and humidity readings.', 'Adjust the module set point; check fans and heat exchangers.', 'Wipe condensation — water floating near electronics is a hazard.'],
    esc: 'If the trend continues or electronics overheat: notify ground.', src: ['std2'] },
  { id: 'SHIP-08', cat: 'ship', title: 'Communications loss with Earth', q: 'comms loss no signal communication earth radio lost contact perdida de comunicacion sin senal tierra radio',
    a: 'NovaCare is designed for this: everything keeps working on board and syncs when the link returns.',
    steps: ['Keep logging readings — they upload when the link is back.', 'Follow the loss-of-communication procedure and keep a written log of decisions.', 'Medical questions: use the onboard protocols and the Crew Medical Officer.'],
    esc: 'If the loss lasts longer than planned, follow the autonomous-operations plan for your mission.', src: ['ei'] },
  { id: 'SHIP-09', cat: 'ship', title: 'Noise in the cabin', q: 'noise loud fan noise hearing ruido fuerte ventilador oido',
    a: 'Constant fan and pump noise disturbs sleep and, over time, hearing.',
    steps: ['Wear hearing protection near loud equipment.', 'Report new or louder noises — they can signal a failing fan or pump.', 'Use earplugs in the sleep station.'],
    esc: 'Ringing ears or hearing loss: tell the Crew Medical Officer.', src: ['std2'] },
  { id: 'SHIP-10', cat: 'ship', title: 'Exercise equipment broken', q: 'treadmill broken exercise device bike resistive device broken equipo de ejercicio roto caminadora bicicleta',
    a: 'A missed exercise prescription quickly costs bone and muscle.',
    steps: ['Report the failure and try the repair procedure.', 'Switch to another device or to bodyweight and resistance-band exercises.', 'Log what you did so the plan can be adjusted.'],
    esc: 'If no device is available for several days: ask ground for an alternative plan.', src: ['fit', 'bone'] },
  { id: 'SHIP-11', cat: 'ship', title: 'Food supply running low or spoiled food', q: 'food low food shortage spoiled food comida escasa poca comida comida en mal estado',
    a: 'The food supply is fixed; calories and nutrients matter for health and mood.',
    steps: ['Check meal packs in the ship inventory and the days left.', 'Discard packs that are swollen, leaking or smell wrong.', 'Ask ground to re-plan menus to keep calories and protein.'],
    esc: 'Weight loss or not enough food until resupply: notify ground.', src: ['food'] },
  { id: 'SHIP-12', cat: 'ship', title: 'Mould, odour or microbial growth', q: 'mold mould odor smell bacteria microbial growth hongo moho mal olor bacterias',
    a: 'Humidity and closed air let microbes grow behind panels and in fabrics.',
    steps: ['Wear gloves and a mask.', 'Clean the area with disinfectant wipes and dry it.', 'Find and fix the moisture source.', 'Take a sample if the mission has a microbial kit.'],
    esc: 'Recurring growth or crew with respiratory symptoms: notify ground.', src: ['micro', 'std2'] },
  { id: 'SHIP-13', cat: 'ship', title: 'Medical kit running low', q: 'medical kit low supplies running out medicine out of stock botiquin bajo pocos medicamentos agotado',
    a: 'NovaCare tracks medical supplies in the ship inventory and warns at the minimum.',
    steps: ['Open Crew → Ship inventory → filter "Low or out".', 'Use the standard medical kit list to see what is missing.', 'Ask ground to add items to the next resupply.'],
    esc: 'If an essential item (epinephrine, oxygen, AED) is out: tell the commander and ground now.', src: ['med'] },
  { id: 'SHIP-14', cat: 'ship', title: 'Lighting and day–night cycle', q: 'lighting light circadian day night cycle sunrise iluminacion luz ciclo dia noche',
    a: 'Station crews see a sunrise every 90 minutes; lighting is used to keep the body clock steady.',
    steps: ['Bright, blue-rich light in the morning; warm dim light in the evening.', 'Keep the same wake and sleep times.', 'Cover windows in the sleep station.'],
    esc: 'Persistent sleep problems: see "Insomnia".', src: ['sleep', 'std2'] },
];
const KBI = Object.fromEntries(KB.map((e) => [e.id, e]));

/* ---------- local search (BM25 over title + aliases + text) ---------- */
const KBSearch = (() => {
  const STOP = new Set('a an the is are am i my me you we to of in on at for and or with what how do does can should it this that de la el los las un una y o que como para por con mi me es en se lo le hay tengo esta estoy feel feeling felt siento sentir senti muy very have has o os as do da um uma com nao meu minha eu tenho estou sinto posso qual muito mas voce le les des du une pour avec ne pas est mon ma mes je suis sens peux comment quel tres mais vous ai aussi tout tous cest quoi qui'.split(' '));
  const GENERIC = new Set('pain dolor duele hurt ache sore weird strange raro rara extrano extrana bad mal problem problema sick symptom sintoma dor doi douleur sintoma symptome'.split(' '));
  const tok = (s) => fold(s).replace(/[^a-z0-9₂ ]+/g, ' ').split(/\s+/).filter((w) => w.length > 2 && !STOP.has(w)).map((w) => w.replace(/(ing|es|s)$/, '').slice(0, 9));
  // general fallbacks (GEN-…) are not searched: they answer only when nothing specific matches
  const docs = KB.filter((e) => !e.fallback).map((e) => { const other = typeof I18N !== 'undefined' ? tok(I18N.kbWords(e.id)) : []; // titles and words in every language
    const words = [...tok(e.title), ...tok(e.title), ...tok(e.q), ...tok(e.q), ...tok(e.a), ...other, ...other]; const tf = {}; words.forEach((w) => { tf[w] = (tf[w] || 0) + 1; }); return { e, tf, len: words.length }; });
  const avg = docs.reduce((n, d) => n + d.len, 0) / docs.length;
  const df = {}; docs.forEach((d) => Object.keys(d.tf).forEach((w) => { df[w] = (df[w] || 0) + 1; }));
  const vocab = Object.keys(df);
  /* Edit distance, stopped early once it is over the limit. */
  function near(a, b, max) {
    if (Math.abs(a.length - b.length) > max) return false;
    let prev = Array.from({ length: b.length + 1 }, (_, j) => j);
    for (let i = 1; i <= a.length; i++) {
      const cur = [i]; let best = i;
      for (let j = 1; j <= b.length; j++) { cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1)); best = Math.min(best, cur[j]); }
      if (best > max) return false; prev = cur;
    }
    return prev[b.length] <= max;
  }
  /* A word that is not in the base still counts if it is a typo or a close spelling of one that is
     ("migrana" → "migraine", "diarea" → "diarrea"), at a lower weight. */
  const fuzzyCache = {};
  function expand(w) {
    if (df[w]) return [[w, 1]];
    if (fuzzyCache[w]) return fuzzyCache[w];
    const max = w.length >= 9 ? 2 : w.length >= 5 ? 1 : 0; // 7-letter words with 2 edits matched unrelated words ("francia" → "fracas")
    const pre = (v) => { let i = 0; while (i < v.length && i < w.length && v[i] === w[i]) i++; return i; };
    const out = !max ? [] : vocab.filter((v) => v.length >= 4 && ((v.length >= 5 && (v.startsWith(w) || w.startsWith(v))) || near(w, v, max) || (pre(v) >= 5 && pre(v) >= Math.min(v.length, w.length) - 2))).map((v) => [v, 0.75]);
    return (fuzzyCache[w] = out);
  }
  /** Best matching entries with a score; empty when nothing is relevant. */
  function search(q, n = 3) {
    const terms = [...new Set(tok(q))]; if (!terms.length) return [];
    const ex = terms.map(expand);
    return docs.map((d) => {
      let s = 0, specific = false;
      ex.forEach((alts, i) => {
        let best = 0; // each word of the question counts once, by its best spelling
        alts.forEach(([w, k]) => { const f = d.tf[w]; if (!f) return; const idf = Math.log(1 + (docs.length - df[w] + 0.5) / (df[w] + 0.5)); best = Math.max(best, k * idf * (f * 2.2) / (f + 1.2 * (0.25 + 0.75 * d.len / avg))); });
        s += best; if (best && !GENERIC.has(terms[i])) specific = true;
      });
      return { e: d.e, s: specific ? s : 0 }; // "pain" alone does not say which protocol
    }).filter((x) => x.s >= 2.2).sort((a, b) => b.s - a.s).slice(0, n);
  }
  return { search };
})();

/* ---------- protocol approval: nothing is "validated" until a medical officer approves it ----------
   Every onboard protocol (KB-…), emergency protocol (EMG-…), the medication rules (RULES) and the finding
   rules (ANALYSIS) start as drafts. The Crew Medical Officer approves them from the mission log terminal
   (/approve KB-MED-09 ISS Medical Checklist), naming the document they checked it against. The approval
   is shared with the crew through the same channel as alerts, and every answer, recommendation and
   emergency protocol says whether what it uses is approved or still a draft. */
const PROTOCOL_GROUPS = { RULES: 'Medication rules engine', ANALYSIS: 'Finding and follow-up rules' };

const Protocols = (() => {
  const key = () => 'novacare.approvals:' + ((Auth.user() && Auth.user().crew) || '-');
  const stored = () => { try { return JSON.parse(localStorage.getItem(key())) || {}; } catch (e) { return {}; } };
  const keep = (o) => { try { localStorage.setItem(key(), JSON.stringify(o)); } catch (e) { /* ignore */ } };
  function ids() {
    return [...KB.map((e) => 'KB-' + e.id), ...(typeof EMERGENCIES !== 'undefined' ? EMERGENCIES.map((e) => 'EMG-' + e.id) : []), ...Object.keys(PROTOCOL_GROUPS)];
  }
  const norm = (id) => { const u = String(id || '').trim().toUpperCase(); return ids().find((x) => x.toUpperCase() === u) || null; };
  const nameOf = (id) => { if (PROTOCOL_GROUPS[id]) return PROTOCOL_GROUPS[id]; const k = KB.find((e) => 'KB-' + e.id === id); if (k) return k.title; const e = typeof EMG !== 'undefined' && EMG[id.replace(/^EMG-/, '')]; return e ? e.name : id; };
  /** Current approvals: the crew's shared records, newest last, on top of what this device remembers. */
  function all() {
    const out = { ...stored() };
    const recs = typeof Crew !== 'undefined' ? Crew.alerts().filter((a) => a.type === 'approve' || a.type === 'revoke').sort((a, b) => a.createdAt.localeCompare(b.createdAt)) : [];
    recs.forEach((a) => { const [id, source] = String(a.note || '').split('|'); if (!id) return; if (a.type === 'revoke') delete out[id]; else out[id] = { by: a.fromName, at: a.createdAt, md: a.md, source: source || '' }; });
    keep(out); return out;
  }
  const status = (id) => all()[id] || null;
  /** Who may sign: the Crew Medical Officer. A guest may, for training, and it says so. */
  function signer() {
    const u = Auth.user(); if (!u) return null; const name = (state && state.name) || u.name;
    if (u.role === 'Crew Medical Officer') return `${name}, Crew Medical Officer`;
    if (u.guest) return `${name} (training — not valid for real care)`;
    return null;
  }
  function approve(raw, source) {
    const id = norm(raw); if (!id) return `Unknown protocol “${raw}”. Type /protocols to see the ids.`;
    const by = signer(); if (!by) return 'Only the Crew Medical Officer can approve protocols.';
    if (!source) return `Name the document you checked it against, e.g. /approve ${id} ISS Medical Checklist`;
    const me = Crew.members()[0]; Crew.record(me, 'approve', `${id}|${source}`, by);
    return `${id} (${nameOf(id)}) approved by ${by}, checked against ${source}.`;
  }
  function revoke(raw) {
    const id = norm(raw); if (!id) return `Unknown protocol “${raw}”.`;
    const by = signer(); if (!by) return 'Only the Crew Medical Officer can withdraw an approval.';
    Crew.record(Crew.members()[0], 'revoke', id, by); return `${id} is a draft again.`;
  }
  /** Plain words for an answer or a recommendation. */
  function text(id) {
    const s = id && status(id);
    if (!id) return 'no onboard protocol';
    return s ? `approved by ${s.by} on ${new Date(s.at).toLocaleDateString(typeof I18N !== 'undefined' ? I18N.locale() : 'en-US', { month: 'short', day: 'numeric' })}${s.source ? `, checked against ${s.source}` : ''}`
      : 'draft — not yet approved by a medical officer; confirm with the Crew Medical Officer';
  }
  const approved = (id) => !!status(id);
  function summary() {
    const a = all(); const list = ids(); const ok = list.filter((id) => a[id]);
    return { total: list.length, approved: ok.length, drafts: list.filter((id) => !a[id]) };
  }
  return { ids, norm, nameOf, all, status, approve, revoke, text, approved, summary, signer };
})();
